/* Academic Integrity Casebook. No external services or automatic sending. */
'use strict';
const DEFAULT_NR_RATIONALE="The available evidence does not establish, by a preponderance of the evidence, that the student committed the alleged academic integrity violation. Accordingly, the student is found not responsible.";
const DEFAULT_SANCTION_RATIONALE="The sanctions are proportionate to the level of the offense and the assignment\u2019s weight in the course grade, and are consistent with sanctions imposed in similar cases.";
const S = {boot:null,cases:[],detail:null,view:'cases',tab:'overview',commId:null,search:'',filter:'open',caseSort:'number-desc',archive:null,archiveSearch:'',archiveFilter:'all',templateReview:null,templateSelection:'',dirty:false,busy:false,brief:null};
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = esc;
const trim = value=>String(value??'').trim();
const courseLabel = value=>/^\d+$/.test(trim(value))?'Math '+trim(value):trim(value);
const personName = p=>p?.name||'Name not yet confirmed';
const casePath = ()=>`/api/cases/${encodeURIComponent(S.detail.id)}`;
const selected = (a,b)=>String(a??'')===String(b??'')?' selected':'';
const checked = value=>value?' checked':'';
const pretty = value=>String(value??'').replace(/[_-]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const dateText = value=>{if(!value)return 'Not set';const d=new Date(String(value).length===10?`${value}T12:00:00`:value);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'});};
const dateInput = value=>/^\d{4}-\d{2}-\d{2}/.test(value||'')?String(value).slice(0,10):'';
const sizeText = value=>Number(value||0)>1048576?`${(value/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(Number(value||0)/1024))} KB`;
const localToday = ()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const isPartyOverdue = p=>p.status!=='Closed'&&p.due_date&&dateInput(p.due_date)<localToday();
const isOverdue = c=>!c.closed&&Boolean((c.due_date&&dateInput(c.due_date)<localToday())||(c.parties||[]).some(isPartyOverdue));
const nextCaseDue = c=>[c.due_date,...(c.parties||[]).filter(p=>p.status!=='Closed').map(p=>p.due_date)].filter(Boolean).sort()[0]||'';
const PARTY_STATUSES=['Review needed','Open','Awaiting response','Meeting','Outcome','Appeal/hearing','Closed'];
function safeLocal(value){try{const u=new URL(value,location.origin);return u.origin===location.origin&&['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function safeWeb(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function deadlineText(iso){if(!iso)return '';const d=new Date(iso+'T12:00:00');return d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});}
function updateEmailDeadline(form){const letter=S.detail?.communications.find(x=>x.id===S.commId);if(letter?.deadline_business_days!==5)return;const calendar=S.boot.business_calendar;const raw=form.elements.date.value;if(!raw)return;const d=new Date(raw+'T12:00:00');let count=0;while(count<5){d.setDate(d.getDate()+1);if(!calendar.years.includes(d.getFullYear())){toast('Update the Rutgers holiday calendar before using this send date.',true);return;}const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(d.getDay()!==0&&d.getDay()!==6&&!calendar.closed_dates.includes(iso))count++;}const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const display=form.elements.response_deadline_display;form.elements.body.value=form.elements.body.value.split(deadlineText(display.dataset.deadline)).join(deadlineText(iso));display.value=deadlineText(iso);display.dataset.deadline=iso;}
function assessmentValue(...values){return values.find(v=>typeof v==='string'&&v.trim()&&v.trim().toUpperCase()!=='[ASSESSMENT]')?.trim()||'';}
function violationRow(v={}){const categories=['Cheating','Plagiarism','Fabrication','Facilitation of dishonesty','Academic sabotage','Violation of research or professional ethics','Other'];return `<div class="grid two violation-row"><div><label>Violation category</label><select data-violation-category><option value="">Not selected</option>${categories.map(k=>`<option value="${attr(k)}"${selected(v.category,k)}>${esc(k)}</option>`).join('')}</select></div><div><label>Level</label><select data-violation-level><option value="">Select level</option>${['1','2','3'].map(k=>`<option value="${k}"${selected(v.level,k)}>Level ${k}</option>`).join('')}</select></div><div class="span-all"><label>Description / counts</label><input data-violation-description value="${attr(v.description||'')}" placeholder="Describe this violation"></div></div>`;}
let sanctionRowCounter=0;
function sanctionParameters(item,picked={},suffix=''){
 const values=picked.parameters||{};
 if(item.id==='probation'){
  const old=values['PROBATION END']||'';const legacy=old.match(/(?:the )?(beginning|end) of (?:the )?((?:Spring|Summer|Fall|Winter)\s+20\d{2})(?: semester)?/i);const mode=values['PROBATION MODE']||(legacy?legacy[1].toLowerCase():/^\d{4}-\d{2}-\d{2}$/.test(old)?'date':'end');
  return `<div><label>Probation ends</label><select data-probation-mode data-sanction-param="PROBATION MODE" name="probation_mode${suffix}">${[['date','Specific date'],['beginning','Beginning of a semester'],['end','End of a semester']].map(([v,label])=>`<option value="${v}"${selected(mode,v)}>${label}</option>`).join('')}</select></div><div data-probation-part="date"${mode==='date'?'':' hidden'}>${field('End date','probation_date'+suffix,values['PROBATION DATE']||(/^\d{4}-\d{2}-\d{2}$/.test(old)?old:''),'date','data-sanction-param="PROBATION DATE"')}</div><div data-probation-part="semester"${mode==='date'?' hidden':''}>${field('Semester','probation_semester'+suffix,values['PROBATION SEMESTER']||legacy?.[2]||'','text','data-sanction-param="PROBATION SEMESTER" placeholder="Fall 2026"')}<p class="help">For example, End + Fall 2026 becomes “through the end of the Fall 2026 semester.”</p></div>`;
 }
 return Object.entries(item.fields||{}).map(([key,label])=>field(label,`sanction_${item.id}_${key}${suffix}`,values[key]||'','text',`data-sanction-param="${attr(key)}"`)).join('');
}
function sanctionSingle(group,chosen,sanctions,decisions={}){const items=sanctions.filter(x=>x.category===group);const picked=chosen.find(x=>items.some(y=>y.id===x.id));return `<section data-sanction-group="${group}"><h3>${esc(pretty(group))}</h3><label>Sanction</label><select data-sanction-single="${group}"><option value="">Select a sanction or None</option><option value="__none__"${selected(decisions[group],'none')}>None</option>${items.map(x=>`<option value="${attr(x.id)}"${selected(picked?.id,x.id)}>${esc(x.label)}</option>`).join('')}</select>${items.map(x=>`<div class="section-gap" data-sanction-params="${attr(x.id)}"${picked?.id===x.id?'':' hidden'}>${sanctionParameters(x,chosen.find(y=>y.id===x.id)||{})}</div>`).join('')}</section>`;}
function academicSanctionRow(picked={},approved=false){const items=S.boot.integrity_catalog?.sanctions?.filter(x=>x.category==='academic')||[];const suffix='_'+(++sanctionRowCounter);return `<div class="section-gap" data-academic-row data-extra-approved="${approved?'true':'false'}"><div class="actions"><select aria-label="Academic sanction" data-academic-sanction data-previous="${attr(picked.id||'')}"><option value="">Select sanction</option>${items.map(x=>`<option value="${attr(x.id)}"${selected(picked.id,x.id)}>${esc(x.label)}</option>`).join('')}</select><button type="button" data-action="remove-academic">Remove</button></div>${items.map(x=>`<div class="section-gap" data-sanction-params="${attr(x.id)}"${picked.id===x.id?'':' hidden'}>${sanctionParameters(x,picked.id===x.id?picked:{},suffix)}</div>`).join('')}</div>`;}
function outcomeControls(c){if(!c.outcome_kind)return '';const q=c.outcome_choices||{};const sanctions=S.boot.integrity_catalog?.sanctions||[];const chosen=q.sanctions||[];const academic=chosen.filter(x=>sanctions.some(y=>y.id===x.id&&y.category==='academic'));return `<details open class="section-gap"><summary>Finding and sanction selections</summary><p class="help">Selections build the wording; they do not change the case finding or send a letter. After changing selections, click Build letter from selections. Changing the letter date also rebuilds calculated deadlines from these selections.</p>${field('Assessment','outcome_assessment',assessmentValue(q.assessment,c.assessment,S.detail.assessment),'text','placeholder="Final Exam"')}<h3>Violations</h3><div id="violation-rows">${(q.violations?.length?q.violations:[{}]).map(violationRow).join('')}</div><button type="button" data-action="add-violation">+ Add violation</button>${c.outcome_kind==='not-responsible'?'':`${textarea('Finding rationale','outcome_rationale',q.rationale||'','rows="6"')}<input type="hidden" name="rationale_file_id" value="${attr(c.rationale_source?.file_id||'')}">${c.rationale_source?`<p class="help">Prefilled from <a href="${attr(safeLocal(c.rationale_source.url))}" target="_blank" rel="noopener">${esc(c.rationale_source.name)}</a>. Review and edit before building.</p>`:''}<button type="button" data-action="load-rationale">Use saved rationale</button><h3>Sanctions</h3>${sanctionSingle('disciplinary',chosen,sanctions,q.sanction_decisions||{})}${sanctionSingle('educational',chosen,sanctions,q.sanction_decisions||{})}<section data-academic-group><h3>Academic</h3><p class="help">Usually choose one academic sanction; multiple sanctions can overlap or contradict one another.</p><label>Academic sanction decision</label><select data-academic-decision><option value="">Select an option</option><option value="none"${selected(q.sanction_decisions?.academic,'none')}>None</option><option value="add"${academic.length||q.sanction_decisions?.academic==='selected'?' selected':''}>Add sanctions</option></select><div data-academic-container${academic.length||q.sanction_decisions?.academic==='selected'?'':' hidden'}><div id="academic-sanctions">${academic.map(x=>academicSanctionRow(x,academic.length>1)).join('')}</div><button type="button" data-action="add-academic">Add academic sanction</button></div></section><details><summary>XF / suspension / expulsion procedure</summary><p class="help">The approved hearing section is used automatically. Leave this field blank to use it, or enter reviewed case-specific wording. Use [RESPONSE DEADLINE] for the calculated date. The letter and its rationale serve as the report; no separate report attachment is required by this app.</p>${textarea('Hearing and response wording','outcome_hearing_text',q.hearing_text||'','rows="5"')}</details>`}<button class="primary section-gap" type="button" data-action="compose-outcome">Build letter from selections</button></details>`;}
function selectionParameters(container,id){const wrapper=$$('[data-sanction-params]',container).find(x=>x.dataset.sanctionParams===id);return Object.fromEntries($$('[data-sanction-param]',wrapper).map(x=>[x.dataset.sanctionParam,x.value]));}
function outcomeChoices(form){const c=S.detail.communications.find(x=>x.id===S.commId);if(!c?.outcome_kind)return null;const fields=form.elements;const violations=$$('.violation-row',form).map(row=>({category:row.querySelector('[data-violation-category]').value,level:row.querySelector('[data-violation-level]').value,description:row.querySelector('[data-violation-description]').value})).filter(v=>v.category);const sanctions=[];const sanction_decisions={};for(const picker of $$('[data-sanction-single]',form)){sanction_decisions[picker.dataset.sanctionSingle]=picker.value==='__none__'?'none':picker.value?'selected':'';if(picker.value&&picker.value!=='__none__')sanctions.push({id:picker.value,parameters:selectionParameters(picker.closest('[data-sanction-group]'),picker.value)});}const academicDecision=$('[data-academic-decision]',form)?.value||'';sanction_decisions.academic=academicDecision==='none'?'none':academicDecision==='add'?'selected':'';for(const row of academicDecision==='add'?$$('[data-academic-row]',form):[]){const id=row.querySelector('[data-academic-sanction]').value;if(id)sanctions.push({id,parameters:selectionParameters(row,id)});}return {assessment:assessmentValue(fields.outcome_assessment?.value,c.assessment,S.detail.assessment),violations,sanctions,sanction_decisions,rationale:fields.outcome_rationale?.value||'',sanction_rationale:fields.outcome_sanction_rationale?.value||'',hearing_text:fields.outcome_hearing_text?.value||''};}
function refreshSanctionParameters(container,id){for(const x of $$('[data-sanction-params]',container))x.hidden=x.dataset.sanctionParams!==id;}
async function academicSelectionChanged(picker){const row=picker.closest('[data-academic-row]');const others=$$('[data-academic-sanction]').filter(x=>x!==picker&&x.value);if(picker.value&&others.some(x=>x.value===picker.value)){toast('That academic sanction is already selected.',true);picker.value=picker.dataset.previous||'';return;}if(picker.value&&others.length&&row.dataset.extraApproved!=='true'){if(!await window.GWorksDialogs.confirm('Academic sanctions can overlap or contradict each other. Add another academic sanction anyway?')){picker.value=picker.dataset.previous||'';return;}row.dataset.extraApproved='true';}picker.dataset.previous=picker.value;refreshSanctionParameters(row,picker.value);markDirty();}
function reportSelect(label,name,value,options){return `<div><label>${esc(label)}</label><select name="${attr(name)}"><option value="">Not recorded</option>${options.map(v=>`<option value="${attr(v)}"${selected(value,v)}>${esc(v)}</option>`).join('')}</select></div>`;}
function reportingControls(c){if(c.delivery==='email')return '';const r=c.reporting||{};const q=c.outcome_choices||{};const schema=S.boot.report_schema?.fields||[];const courseDefault=S.detail.course==='135'?'Calculus I for Life Sciences':'';return `<details open class="section-gap"><summary>Final reporting form details</summary><p class="help">These answers are saved locally and exported for the Chrome helper. Missing answers remain flagged; nothing is submitted. Incident date and student identifiers come from Overview.</p><div class="grid two"><div><label>Instructor ${!S.detail.contacts?.confirmed_at?'<span class="input-needed"> • Needs confirmation</span>':''}</label><p>${esc(S.detail.contacts?.instructor?.name||r.instructor||'Not confirmed')}</p><button type="button" data-action="review-contacts">Review complainant and instructor</button></div>${field('Course name','report_course_name',r.course_name||courseDefault)}${field('Full course number','report_course_number',r.course_number||(courseDefault?'01:640:135':''))}${reportSelect('Did the student meet or communicate?','report_communicated',r.communicated,['Yes','No'])}${reportSelect('Did the student admit responsibility?','report_admitted',r.admitted,['Yes','No','No meeting/communication'])}${reportSelect('Did this involve prohibited AI use?','report_ai_use',r.ai_use,['YES','NO','Not Sure'])}</div><p class="help">Violation categories, levels, and findings come from the letter selections above.</p>${textarea('Decision rationale for the reporting form','report_decision_rationale',r.decision_rationale||(c.outcome_kind==='not-responsible'?DEFAULT_NR_RATIONALE:q.rationale||''),'rows="4" required')}${textarea('Recommended sanctions (optional override; otherwise uses the letter)','report_sanctions_text',r.sanctions_text||'','rows="3"')}${textarea('Rationale for sanctions (reporting form only)','report_sanction_rationale',r.sanction_rationale||q.sanction_rationale||(c.outcome_kind==='not-responsible'?'Not applicable — not responsible.':DEFAULT_SANCTION_RATIONALE),'rows="3"')}${textarea('Student explanation','report_explanation',r.explanation||'',`rows="3"${r.communicated==='Yes'?' required':''}`)}${textarea('Additional notes for the report','report_additional_notes',r.additional_notes||'','rows="3"')}<p class="help">A copy of the submitted report is always requested for your email. Attach the outcome PDF and any additional evidence manually.</p></details>`;}
function reportingChoices(form){const c=S.detail.communications.find(x=>x.id===S.commId);if(c.delivery==='email')return null;const e=form.elements;const value=key=>e.namedItem('report_'+key)?.value||'';const r={};for(const key of ['instructor','course_name','course_number','communicated','admitted','ai_use','decision_rationale','sanctions_text','sanction_rationale','explanation','additional_notes'])r[key]=value(key);r.email_copy=true;r.instructor=S.detail.contacts?.instructor?.name||c.reporting?.instructor||'';return r;}
function errorText(error){return error instanceof Error?error.message:'Something went wrong. Please try again.';}
let toastTimer;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.className='';},error?8500:4200);}
async function api(path,body,options={}){const init={method:body===undefined?'GET':'POST',...options,headers:{...(body===undefined?{}:{'Content-Type':'application/json','X-App-Token':S.boot?.token||''}),...(options.headers||{})}};if(body!==undefined)init.body=JSON.stringify(body);const response=await fetch(path,init);let data;try{data=await response.json();}catch{throw new Error('The local app did not return a response. Please reopen the casebook.');}if(!response.ok)throw new Error(data.error||data.message||'The request could not be completed.');return data;}
function needsInput(control,form){
 if(control.name==='reviewed'&&control.type==='checkbox')return !control.checked;
 if(control.disabled||control.readOnly||['hidden','checkbox','radio','button','submit','file'].includes(control.type)||control.closest('[hidden]'))return false;
 const names=new Set(['outcome_assessment','outcome_rationale','title','date','subject','salutation','body','report_instructor','report_course_name','report_course_number','report_communicated','report_admitted','report_ai_use','report_decision_rationale','report_sanction_rationale']);
 let needed=control.required||names.has(control.name)||control.hasAttribute('data-violation-category')||control.hasAttribute('data-violation-level')||control.hasAttribute('data-academic-sanction')||control.hasAttribute('data-sanction-single')||control.hasAttribute('data-academic-decision')||control.hasAttribute('data-sanction-param');
 if(control.name==='report_explanation')needed=form.elements.namedItem('report_communicated')?.value==='Yes';
 if(!needed)return false;
 const value=String(control.value||'').trim();return !value||/\[[A-Z][A-Z _-]{2,}\]/.test(value);
}
function updateInputMarkers(){
 const form=$('form[data-form="save-letter"]');if(!form?.querySelectorAll)return;
 const explanation=form.elements?.namedItem('report_explanation');if(explanation)explanation.required=form.elements.namedItem('report_communicated')?.value==='Yes';
 for(const marker of $$('[data-input-marker]',form))marker.remove();
 const controls=$$('input,select,textarea',form);const missing=[];
 for(const control of controls){const needed=needsInput(control,form);control.classList.toggle('needs-input-control',needed);if(!needed)continue;missing.push(control);const label=control.labels?.[0]||control.parentElement?.querySelector('label');if(label){const mark=document.createElement('span');mark.className='input-needed';mark.dataset.inputMarker='';mark.textContent=' • Needs input';label.append(mark);}}
 for(const section of $$('details',form)){const count=missing.filter(x=>section.contains(x)).length;if(!count)continue;const summary=section.querySelector('summary');if(summary){const mark=document.createElement('span');mark.className='input-needed';mark.dataset.inputMarker='';mark.textContent=` • ${count} need input`;summary.append(mark);}}
 const count=form.querySelector('[data-input-count]');if(count)count.textContent=missing.length?`${missing.length} fields need input`:'Fields filled — review the wording before signing.';
 const next=form.querySelector('[data-action="next-input"]');if(next)next.disabled=!missing.length;
 return missing;
}
function nextMissingInput(){const fields=updateInputMarkers()||[];if(!fields.length)return;const active=document.activeElement;const index=fields.indexOf(fields.includes(active)?active:S.lastInputTarget);const next=fields[(index+1)%fields.length];S.lastInputTarget=next;for(let p=next.parentElement;p;p=p.parentElement){if(p.tagName==='DETAILS')p.open=true;}next.scrollIntoView({behavior:'smooth',block:'center'});next.focus({preventScroll:true});}
function markDirty(value=true){S.dirty=value;if(value)updateInputMarkers();$$('[data-unsaved]').forEach(el=>{el.textContent=value?'Unsaved changes':'';});}
async function leaveDraft(){if(window.GWorksDialogs.busy)return false;if(!S.dirty)return true;if(!await window.GWorksDialogs.confirm('You have unsaved changes. Leave this screen and discard those changes?'))return false;markDirty(false);return true;}
function modal(title,body,footer='',wide=false){const el=$('#modal');el.className=wide?'wide':'';el.innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="quiet" data-action="close-modal" aria-label="Close dialog">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;el.showModal();}
function closeModal(){const el=$('#modal');if(el.open)el.close();el.innerHTML='';}
function field(label,name,value='',type='text',extra=''){return `<div><label for="${attr(name)}">${esc(label)}</label><input id="${attr(name)}" name="${attr(name)}" type="${attr(type)}" value="${attr(value)}" ${extra}></div>`;}
function textarea(label,name,value='',extra=''){return `<div><label for="${attr(name)}">${esc(label)}</label><textarea id="${attr(name)}" name="${attr(name)}" ${extra}>${esc(value)}</textarea></div>`;}
function partyOptions(value='',allowShared=true){return `${allowShared?`<option value=""${selected(value,'')}>Shared / whole case</option>`:''}${(S.detail?.parties||[]).map(p=>`<option value="${attr(p.id)}"${selected(value,p.id)}>${esc(personName(p))}</option>`).join('')}`;}
function templateLabel(kind){return S.boot?.templates?.find(t=>t.id===kind)?.label||pretty(kind);}
function caseBadge(c){return c.status_review?'<span class="badge amber">Status not reviewed</span>':c.closed?'<span class="badge gray">Closed</span>':isOverdue(c)?'<span class="badge amber">Past due</span>':`<span class="badge">${esc(c.status||'Open')}</span>`;}
function shell(){return `<header class="app-header"><div class="brand"><div class="brand-mark">AI</div><div><div class="brand-name">Academic Integrity</div><div class="brand-subtitle">Math Department · Facilitator Casebook</div></div></div><nav class="main-nav" aria-label="Main navigation">${[['cases','Cases'],['templates','Templates'],['guidance','RU Guidance'],['settings','Settings']].map(([id,label])=>`<button data-action="nav" data-view="${id}" class="${S.view===id?'active':''}"${S.view===id?' aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="local-label">Local and private</div></header><main class="page" id="page"></main>`;}
function render(){const el=$('#app');el.innerHTML=shell();if(S.view==='cases')renderCases();else if(S.view==='archive')renderArchive();else if(S.view==='guidance')renderGuidance();else if(S.view==='templates')renderTemplates();else renderSettings();}
function renderCases(){const open=S.cases.filter(c=>!c.closed&&!c.status_review);$('#page').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Your working desk</div><h1>Cases</h1><p>Track each student’s case, evidence, correspondence, and next steps.</p></div></div>${S.cases.some(c=>c.status_review)?`<div class="notice">${S.cases.filter(c=>c.status_review).length} cases await status review. They are not counted as open or closed yet.</div>`:''}<div class="case-summarybar"><section class="stats" aria-label="Case totals">${[['Open cases',open.length],['Closed cases',S.cases.filter(c=>c.closed).length],['Open cases with active appeals',open.filter(c=>c.active_appeal).length]].map(([label,count])=>`<div class="stat"><div class="number">${count}</div><div class="caption">${label}</div></div>`).join('')}</section><button class="primary" data-action="new-case">+ New case</button></div><div class="case-layout"><aside class="case-sidebar" aria-label="Choose a case"><div class="sidebar-tools"><label class="sr-only" for="case-search">Find a case</label><input id="case-search" type="search" placeholder="Find a case or person…" value="${attr(S.search)}"><label class="sr-only" for="case-filter">Case status</label><select id="case-filter"><option value="open"${selected(S.filter,'open')}>Open cases</option><option value="closed"${selected(S.filter,'closed')}>Closed cases</option><option value="appeals"${selected(S.filter,'appeals')}>Open cases with active appeals</option><option value="review"${selected(S.filter,'review')}>Status not reviewed</option><option value="all"${selected(S.filter,'all')}>All cases</option></select><label class="sr-only" for="case-sort">Sort cases</label><select id="case-sort">${[['name-asc','Name (A–Z)'],['name-desc','Name (Z–A)'],['number-desc','Case number (newest first)'],['number-asc','Case number (oldest first)'],['incident-desc','Incident date (newest first)'],['incident-asc','Incident date (oldest first)'],['priority','Open first / due date']].map(([value,label])=>`<option value="${value}"${selected(S.caseSort,value)}>${label}</option>`).join('')}</select></div><div class="case-list" id="case-list"></div></aside><section id="case-detail" class="case-detail" aria-label="Case details"></section></div><div class="footer-note">Letters are saved locally. The casebook never sends messages or submits a decision.</div>`;renderCaseList();renderCaseDetail();}
function caseSortName(c){
  const p=c.parties?.[0]||{};
  return p.last_name?[p.last_name,p.first_name].filter(Boolean).join(', '):(p.name||c.title||'');
}
function compareCases(a,b){
  const number=c=>Number(String(c.id).replace(/^AI-/,''))||0;
  const newest=()=>number(b)-number(a);
  const direction=S.caseSort.endsWith('-desc')?-1:1;
  if(S.caseSort.startsWith('name-')){
    const an=caseSortName(a),bn=caseSortName(b);
    if(!an!==!bn)return an?-1:1;
    return direction*an.localeCompare(bn,undefined,{sensitivity:'base',numeric:true})||newest();
  }
  if(S.caseSort.startsWith('number-'))return direction*(number(a)-number(b));
  if(S.caseSort.startsWith('incident-')){
    const date=c=>/^\d{4}-\d{2}-\d{2}$/.test(c.incident_date||'')?c.incident_date:'';
    const ad=date(a),bd=date(b);
    if(!ad!==!bd)return ad?-1:1;
    return direction*ad.localeCompare(bd)||newest();
  }
  if(a.closed!==b.closed)return a.closed?1:-1;
  return (a.due_date||'9999').localeCompare(b.due_date||'9999')||String(b.updated||'').localeCompare(String(a.updated||''))||newest();
}
function renderCaseList(){const query=S.search.toLocaleLowerCase();const cases=S.cases.filter(c=>(S.filter==='all'||S.filter==='appeals'&&!c.closed&&c.active_appeal||S.filter==='review'&&c.status_review||S.filter==='closed'&&c.closed||S.filter==='open'&&!c.closed&&!c.status_review)&&[c.id,c.title,c.semester,c.course,...(c.parties||[]).flatMap(p=>[p.name,p.email,p.ruid,p.netid])].join(' ').toLocaleLowerCase().includes(query)).sort(compareCases);$('#case-list').innerHTML=cases.length?cases.map(c=>`<button class="case-item${S.detail?.id===c.id?' active':''}" data-action="open-case" data-id="${attr(c.id)}"><span class="case-topline"><span class="eyebrow">${esc(c.id)}</span>${caseBadge(c)}</span><span class="case-title">${esc(c.parties?.[0]?.first_name&&c.parties?.[0]?.last_name?c.parties[0].last_name+', '+c.parties[0].first_name:c.title||'Untitled case')}</span><span class="case-meta">${esc([c.course?courseLabel(c.course):'',c.semester].filter(Boolean).join(' · ')||'Course and semester not set')}</span><span class="case-meta">${S.caseSort.startsWith('incident-')?'Incident: '+esc(c.incident_date?dateText(c.incident_date):'Date not set'):c.active_appeal?'Active appeal':'Individual case'}${nextCaseDue(c)?` · Due ${esc(dateText(nextCaseDue(c)))}`:''}</span></button>`).join(''):'<div class="empty compact">No cases match this view.</div>';}
function renderCaseDetail(){const el=$('#case-detail');if(!S.detail){el.innerHTML=`<div class="panel empty"><div class="eyebrow">A clear place to begin</div><h2>${S.cases.length?'Select a case':'Start your first case'}</h2><p>${S.cases.length?'Choose a case to view its people, evidence, checklist, and letters.':'Create a case, add the people involved, and upload the materials you received.'}</p><button class="primary" data-action="new-case">+ New case</button></div>`;return;}const c=S.detail;el.innerHTML=`<div class="case-heading"><div><div class="eyebrow">${esc(c.id)}</div><h2>${esc(c.title||'Untitled case')}</h2><div class="meta">${esc([c.course?courseLabel(c.course):'',c.semester].filter(Boolean).join(' · ')||'Add course and semester in Overview')}</div></div>${caseBadge(c)}</div><nav class="tabs" aria-label="Case sections">${[['overview','Overview'],['evidence','Evidence'],['letters','Letters'],['meeting','Meetings'],['activity','Activity']].map(([id,label])=>`<button class="${S.tab===id?'active':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</nav><div id="case-content"></div>`;if(S.tab==='overview')renderOverview();else if(S.tab==='meeting')renderMeetings();else if(S.tab==='evidence')renderEvidence();else if(S.tab==='letters')renderLetters();else renderActivity();}
function caseContactsPanel(){const c=S.detail.contacts||{};const person=role=>c[role]?.name?`${esc(c[role].name)}${c[role].email?` · ${esc(c[role].email)}`:''}`:'Not confirmed';return `<div class="panel"><div class="panel-head"><h2>Complainant and instructor</h2><button type="button" data-action="review-contacts">Review contacts</button></div><p><strong>Complainant:</strong> ${person('complainant')}</p><p><strong>Instructor:</strong> ${person('instructor')}</p>${!c.confirmed_at?'<p class="input-needed">Needs input: confirm both roles before preparing email.</p>':''}</div>`;}
async function contactDialog(data){data=data||await api(`${casePath()}/contacts`);const existing=S.detail.contacts||{};const complainant=existing.complainant||data.complainant||{};const instructor=existing.instructor||data.instructor||{};const relation=existing.instructor_relationship||data.instructor_relationship||'';S.contactReviewSources=data.source_file_ids||(data.source_file_id?[data.source_file_id]:[]);modal('Confirm complainant and instructor',`<form id="contact-form" data-form="case-contacts"><p class="help">Suggestions come from the local report. Confirm each role; the complainant is not assumed to be the instructor.</p>${(data.warnings||[]).map(x=>`<p class="help">${esc(x)}</p>`).join('')}<div class="grid two">${field('Complainant name','complainant_name',complainant.name||'','text','required')}${field('Complainant email','complainant_email',complainant.email||'','email','required')}<div class="span-all"><label>Is the complainant also the instructor?</label><select id="instructor-relationship" name="instructor_relationship" required><option value="">Select an option</option><option value="same"${selected(relation,'same')}>Yes — same person</option><option value="different"${selected(relation,'different')}>No — enter the instructor separately</option></select></div><div class="span-all grid two" data-instructor-fields${relation==='different'?'':' hidden'}>${field('Instructor name','instructor_name',instructor.name||'','text',relation==='different'?'required':'disabled')}${field('Instructor email','instructor_email',instructor.email||'','email',relation==='different'?'required':'disabled')}</div></div></form>`,'<button data-action="close-modal">Later</button><button class="primary" type="submit" form="contact-form">Confirm contacts</button>',true);}
async function emailLetterDialog(){if(!await saveLetter(true))return;const plan=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/email-preview`,{});S.emailPlan=plan;modal('Review email draft',`<p><strong>To:</strong> ${esc(plan.to)}</p><p><strong>CC:</strong> ${esc(plan.cc.join(', '))}</p><p><strong>BCC:</strong> ${esc(plan.bcc.join(', ')||'None')}</p><p><strong>Subject:</strong> ${esc(plan.subject)}</p><label>Body</label><textarea rows="5" readonly>${esc(plan.body)}</textarea>${plan.attachment_url?`<p><strong>Attachment:</strong> <a href="${attr(safeLocal(plan.attachment_url))}" target="_blank" rel="noopener">${esc(plan.attachment_name)}</a></p>`:'<p class="help">Email text; no attachment.</p>'}<p class="help">Opens an unsent Thunderbird compose window. An outcome PDF is attached when applicable. Review recipients, sender account, attachment, and wording there before sending. Nothing is marked sent automatically.</p>`,'<button data-action="close-modal">Cancel</button><button class="primary" data-action="open-thunderbird">Open in Thunderbird</button>',true);}
function overviewField(label,name,value='',type='text',extra=''){const missing=!String(value||'').trim();return field(label,name,value,type,extra).replace('</label>',`${missing?'<span class="input-needed"> • Needs input</span>':''}</label>`).replace('<input ',`<input ${missing?'class="needs-input-control" aria-invalid="true" ':''}`);}
function responseRequired(c){const m=(c.steps||[]).find(s=>s.id==='meeting')||{};return !!c.meeting_response||!(c.closed||m.done||m.skipped);}
function responseLabel(r){return ({awaiting:'Awaiting student response',scheduled:'Meeting arranged',no_response:'No response by the deadline',written:'Written response received'})[r?.status]||'Record the student’s response or check after the deadline';}
function meetingResponseRow(c){
  if(!responseRequired(c))return '';
  const r=c.meeting_response||{},done=['scheduled','no_response','written'].includes(r.status);
  const info=[responseLabel(r),r.response_deadline?'Reply deadline: '+dateText(r.response_deadline):'',r.status==='scheduled'&&r.meeting_date?'Meeting: '+dateText(r.meeting_date)+(r.meeting_time?' at '+r.meeting_time:''):'',r.status==='written'&&r.response_date?'Received: '+dateText(r.response_date):''].filter(Boolean).join(' · ');
  return `<div class="step meeting-response-step${done?' done':''}"><input type="checkbox" aria-label="Student response recorded" disabled${checked(done)}><div class="step-main"><strong>Record student response / meeting arrangements</strong><small class="help">${esc(info)}</small></div><button type="button" class="quiet" data-action="meeting-response">${c.meeting_response?'Edit':'Record response'}</button></div>`;
}
function caseChecklist(c,appeal){
  const route=c.meeting_response?.status,skipMeeting=['no_response','written'].includes(route);
  return (c.steps||[]).filter(item=>!item.optional&&(item.id!=='meeting'||!skipMeeting)).map(item=>{
    const copy={...item};
    if(item.id==='meeting'&&route==='scheduled')copy.label='Hold meeting';
    if(item.id==='evidence'&&route==='written')copy.label='Review written response and complete evidence review';
    copy.response_pending=item.id==='meeting'&&responseRequired(c)&&route!=='scheduled';
    return checklistRow(copy,appeal)+(item.id==='contact'?meetingResponseRow(c):'');
  }).join('');
}
function responseFields(form){
  const status=form.elements.status.value;
  for(const block of form.querySelectorAll('[data-response-for]')){
    const show=block.dataset.responseFor.split(' ').includes(status);block.hidden=!show;
    for(const input of block.querySelectorAll('input,select,textarea'))input.disabled=!show;
  }
  form.elements.meeting_date.required=status==='scheduled';
  form.elements.response_deadline.required=status==='no_response';
  form.elements.response_date.required=['no_response','written'].includes(status);
  form.querySelector('[data-response-date-label]').textContent=status==='written'?'Written response received':'Checked for a reply on';
}
async function meetingResponseDialog(){
  if(!await leaveDraft())return;
  const c=S.detail,r=c.meeting_response||{};
  const contact=(c.communications||[]).filter(l=>(l.kind==='contact'||l.deadline_business_days===5)&&l.sent_at).sort((a,b)=>String(b.sent_at).localeCompare(String(a.sent_at)))[0];
  modal('Student response / meeting arrangements',`<form id="meeting-response-form" data-form="meeting-response"><label for="response-status">Response to the initial contact</label><select id="response-status" name="status">${[['awaiting','Awaiting a reply'],['scheduled','Meeting arranged'],['no_response','No response by the deadline'],['written','Written response received']].map(([value,label])=>`<option value="${value}"${selected(r.status||'awaiting',value)}>${label}</option>`).join('')}</select><div class="response-date-grid section-gap">${field('Response deadline','response_deadline',r.response_deadline||contact?.response_deadline||'','date')}<div data-response-for="scheduled">${field('Meeting date','meeting_date',r.meeting_date||'','date')}</div><div data-response-for="scheduled">${field('Meeting time (optional)','meeting_time',r.meeting_time||'','time')}</div><div data-response-for="no_response written"><label for="response_date" data-response-date-label>Checked for a reply on</label><input id="response_date" name="response_date" type="date" value="${attr(r.response_date||localToday())}"></div></div><p class="help">Use the response deadline communicated to this student. Recording a meeting arrangement does not mark the meeting as held.</p><label class="check-row section-gap" data-response-for="no_response"><input type="checkbox" name="confirmed_no_response"${checked(r.confirmed_no_response)} required><span>I checked: the response deadline has passed and the student has not responded.</span></label><div class="section-gap">${textarea('Notes (optional)','notes',r.notes||'')}</div></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="meeting-response-form">Save response</button>');
  responseFields($('#meeting-response-form'));
}
function checklistRow(item,appealActive){const disabled=item.response_pending||(['appeal-response','appeal-decision'].includes(item.id)&&!appealActive);const when=item.completed_at?dateText(item.completed_at):'Date unknown';return `<div class="step${item.done?' done':''}${disabled?' step-disabled':''}"><input aria-label="${attr(item.label)}" type="checkbox" data-step="${attr(item.id)}" data-party="" id="case-step-${attr(item.id)}"${checked(item.done)}${disabled?' disabled':''}><div class="step-main"><label for="case-step-${attr(item.id)}">${esc(item.label)}</label>${item.response_pending?'<small class="help">Record the student response and meeting arrangements first.</small>':''}${item.skipped?'<small class="help">Not needed</small>':''}${item.done?`<small class="help">${esc(when)}${item.date_basis&&item.date_basis!=='Date unknown'?` · ${esc(item.date_basis)}`:''} <button type="button" class="quiet date-edit" data-action="edit-step-date" data-step-id="${attr(item.id)}">Edit date</button></small>`:''}</div>${!item.optional&&!['intake','report'].includes(item.id)?`<button type="button" class="quiet" data-action="skip-step" data-step-id="${attr(item.id)}" data-skipped="${item.skipped?'true':'false'}">${item.skipped?'Needed':'Not needed'}</button>`:''}</div>`;}
function renderOverview(){const c=S.detail;const contacts=c.contacts||{};const p=c.parties[0];const appealReceived=(c.steps||[]).find(s=>s.id==='appeal-received')?.done;$('#case-content').innerHTML=`<div class="panel"><div class="panel-head"><h2>Case checklist</h2><button data-action="upload-report">Upload incident report</button></div><p class="help">One student, one checklist. Mark an unnecessary step as Not needed. Confirming final reporting submission closes the case.</p><div class="checklist">${caseChecklist(c,appealReceived)}</div><details class="section-gap"${appealReceived?' open':''}><summary>Optional appeal steps</summary><p class="help">Recording an appeal reopens the case. Recording the appeal decision closes it again. Upload appeal statements, responses, and decisions under Evidence.</p><div class="checklist">${(c.steps||[]).filter(s=>s.optional).map(s=>checklistRow(s,appealReceived)).join('')}</div></details></div><div class="panel"><div class="panel-head"><h2>Case details and contacts</h2><button type="button" data-action="toggle-case-status">${c.closed?'Reopen case':'Close case'}</button></div>${c.missing_details?.length?`<p class="input-needed" role="status">Missing details: ${c.missing_details.map(esc).join(', ')}</p>`:''}<form data-form="save-case" data-dirty><div class="case-details-grid">${overviewField('First / given name(s)','first_name',p?.first_name||'')}${overviewField('Last / family name(s)','last_name',p?.last_name||'')}${overviewField('Semester','semester',c.semester)}${overviewField('Course number','course',c.course)}${overviewField('Assessment','assessment',c.assessment)}${overviewField('Incident date','incident_date',dateInput(c.incident_date),'date')}${field('Next due date (optional)','due_date',dateInput(c.due_date),'date')}${overviewField('Complainant name','complainant_name',contacts.complainant?.name)}${overviewField('Complainant email','complainant_email',contacts.complainant?.email,'email')}<div class="case-relationship"><label>Is the complainant also the instructor?${!contacts.instructor_relationship?'<span class="input-needed"> • Needs input</span>':''}</label><select name="instructor_relationship" id="overview-instructor-relationship"><option value="">Select an option</option><option value="same"${selected(contacts.instructor_relationship,'same')}>Yes — same person</option><option value="different"${selected(contacts.instructor_relationship,'different')}>No — different instructor</option></select></div>${overviewField('Instructor name','instructor_name',contacts.instructor?.name)}${overviewField('Instructor email','instructor_email',contacts.instructor?.email,'email')}<details class="span-all case-notes"><summary>Case notes</summary>${textarea('Case notes','notes',c.notes)}</details></div><p class="help">Status: ${c.closed?'Closed':'Open'}. Close or reopen this case at any time using the button above. Saving complete contact details confirms them for email.</p><div class="actions section-gap"><button class="primary" type="submit">Save case</button><button type="button" data-action="review-contacts">Review report contacts</button></div></form></div><div class="panel case-people-panel"><div class="panel-head"><h2>People involved</h2>${p?`<button data-action="edit-party" data-id="${attr(p.id)}">Edit student</button>`:'<button data-action="add-party">Add student</button>'}</div>${p?`<article class="party-card"><h3>${esc(p.name)}</h3><p>${p.ruid?`RUID ${esc(p.ruid)}`:'<span class="input-needed">RUID • Needs input</span>'} · ${p.email?esc(p.email):'<span class="input-needed">Student email • Needs input</span>'}</p>${p.notes?`<p class="help">${esc(p.notes)}</p>`:''}</article>`:'<p class="input-needed">Student name, RUID, and email • Needs input. Upload an incident report to populate this case.</p>'}</div>`;}
let meetingTimer=null;let meetingSaving=null;
function renderMeetings(){const meetings=S.detail.meetings||[];const m=S.meetingId===undefined?(meetings.at(-1)||{}):(meetings.find(x=>x.id===S.meetingId)||{});$('#case-content').innerHTML=`<div class="panel"><div class="panel-head"><h2>Meeting</h2><button data-action="new-meeting">New meeting</button></div><p class="help">Notes save automatically while you type. Dates and times use your local time. Completing the meeting is a separate confirmation.</p>${meetings.length?`<div class="actions section-gap">${meetings.map(x=>`<button data-action="open-meeting" data-id="${attr(x.id)}">${esc(dateText(x.date))}${x.time?' · '+esc(x.time):''}</button>`).join('')}</div>`:''}<form data-form="save-meeting" data-meeting-id="${attr(m.id||'')}" data-dirty><div class="grid two">${field('Meeting date','meeting_date',m.date||localToday(),'date')}${field('Start time','meeting_time',m.time||'','time')}${field('End time (optional)','meeting_end_time',m.end_time||'','time')}${field('Location / meeting link (optional)','meeting_location',m.location||'')}</div>${textarea('Live meeting notes','meeting_notes',m.notes||'','rows="14" spellcheck="true"')}<p id="meeting-save-status" class="help" role="status">${m.updated?'Saved '+esc(new Date(m.updated).toLocaleString()):'Start typing to save this meeting.'}</p><div class="actions"><button type="submit" class="primary">Save meeting</button><button type="button" data-action="complete-meeting">Save and mark meeting complete</button></div></form></div>`;}
function meetingPayload(form){return {id:form.dataset.meetingId||'',date:form.elements.meeting_date.value,time:form.elements.meeting_time.value,end_time:form.elements.meeting_end_time.value,location:form.elements.meeting_location.value,notes:form.elements.meeting_notes.value};}
async function saveMeeting(complete=false){clearTimeout(meetingTimer);if(meetingSaving)await meetingSaving;const form=$('form[data-form="save-meeting"]');if(!form)return;const payload=meetingPayload(form);payload.complete=complete;const snapshot=JSON.stringify(meetingPayload(form));const status=$('#meeting-save-status');if(status)status.textContent='Saving…';meetingSaving=api(`${casePath()}/meetings`,payload);try{const result=await meetingSaving;if(S.detail?.id!==result.case.id)return;S.detail=result.case;form.dataset.meetingId=result.meeting_id;S.meetingId=result.meeting_id;if(snapshot===JSON.stringify({...meetingPayload(form),id:payload.id})){markDirty(false);if(status)status.textContent='Saved '+new Date().toLocaleTimeString();}else if(status)status.textContent='Saving new changes…';if(complete){S.cases=(await api('/api/cases')).cases||[];renderCaseList();toast('Meeting saved and checklist completed.');}}catch(error){if(status)status.textContent='Not saved: '+errorText(error);throw error;}finally{meetingSaving=null;}}
async function intakeDialog(data){const students=data.students||[];if(!students.length){toast('No student details could be read. Enter missing fields in Overview.',true);return;}S.intakeSource=data.source_file_id;modal('Choose this case’s student',`<form id="intake-form" data-form="apply-intake"><p>This report can describe several students. This case will contain only the student selected below.</p><label>Student</label><select name="ruid" required><option value="">Select the student</option>${students.map(p=>`<option value="${attr(p.ruid)}"${selected(data.selected_ruid,p.ruid)}>${esc(p.name)} · ${esc(p.ruid)}</option>`).join('')}</select><h3>Report details</h3><ul>${Object.entries(data.case_fields||{}).map(([key,value])=>`<li>${esc(pretty(key))}: ${esc(value)}</li>`).join('')}${Object.entries(data.contacts||{}).filter(([key,value])=>value&&typeof value==='object').map(([role,value])=>`<li>${esc(pretty(role))}: ${esc(value.name||'Name not found')} · ${esc(value.email||'Email not found')}</li>`).join('')}</ul><label class="check"><input type="checkbox" name="overwrite">Replace existing Overview values with the report values shown here. Unchecked fills blanks only.</label></form>`,'<button data-action="close-modal">Later</button><button class="primary" type="submit" form="intake-form">Use report details</button>');}
function editStepDateDialog(id){const item=S.detail.steps.find(s=>s.id===id);modal('Correct checklist date',`<form id="step-date-form" data-form="step-date" data-step-id="${attr(id)}"><p>${esc(item.label)}</p>${field('Completion date (leave blank for Unknown)','completed_date',dateInput(item.completed_at),'date')}<p class="help">This changes only the recorded date, not the completion or case status.</p></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="step-date-form">Save date</button>');}
const EVIDENCE_TYPES=[['incident-report','Initial incident report'],['email-correspondence','Email correspondence'],['assignment','Assignment or exam submission'],['student-testimony','Student statement or testimony'],['student-meeting-summary','Meeting notes or summary'],['supporting-evidence','Supporting evidence'],['other','Other']];
function renderEvidence(){const c=S.detail;$('#case-content').innerHTML=`<div class="panel"><h2>Add evidence or a case document</h2><button type="button" data-action="rationale-handoff">Prepare AI handoff for rationale</button><button type="button" data-action="handoff-resume">Resume unfinished handoff</button><p class="help">Every file belongs to this student’s case. Meeting notes saved in the Meetings tab also appear here as a student meeting summary.</p><form data-form="upload" class="section-gap"><label for="upload-kind">Document type</label><select id="upload-kind" name="kind">${EVIDENCE_TYPES.map(([id,label])=>`<option value="${id}"${selected(id,'other')}>${label}</option>`).join('')}</select><label for="upload-file">Choose a file</label><input type="file" id="upload-file" name="file" required><p class="help">Up to 50 MB per file. Incident-report extraction is local. Text notes open directly in your browser.</p><div class="actions section-gap"><button class="primary" type="submit">Upload material</button></div></form></div><div class="panel"><div class="panel-head"><h2>Saved materials</h2><span class="badge gray">${(c.files||[]).length} files</span></div><div class="file-list">${(c.files||[]).map(f=>`<article class="file-row"><div class="file-icon">${esc((f.name||'').split('.').pop().slice(0,5))}</div><div class="file-description"><a href="${attr(safeLocal(f.url))}" target="_blank" rel="noopener">${esc(f.name)} ↗</a><p class="help">${esc(EVIDENCE_TYPES.find(([id])=>id===f.kind)?.[1]||'Other')}${f.purpose==='finding-rationale'?' · Finding and rationale':''} · ${esc(sizeText(f.bytes))}</p></div><div class="actions">${f.kind==='incident-report'?`<button data-action="review-intake" data-id="${attr(f.id)}">Extract report details</button>`:''}<button data-action="reclassify-evidence" data-id="${attr(f.id)}">Change category</button><button data-action="delete-evidence" data-id="${attr(f.id)}">Delete</button></div></article>`).join('')||'<div class="empty compact">No materials uploaded for this case.</div>'}</div></div><div class="panel"><h2>Saved rationale handoffs</h2><p class="help">Reviewed packages stay with this case for future use. Downloading does not send anything.</p>${(c.rationale_handoffs||[]).map(h=>`<p><a href="${attr(casePath()+'/handoff/'+encodeURIComponent(h.id)+'/download')}" download="Rationale-handoff.zip">Rationale handoff · ${esc(dateText(h.created))}</a></p>`).join('')||'<p class="help">No reviewed handoffs saved yet.</p>'}</div>`;}
function renderLetters(){const comms=S.detail.communications||[];if(!comms.some(c=>c.id===S.commId))S.commId=comms[0]?.id||null;$('#case-content').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Case correspondence</h2><p class="help">Prepare a draft, check it, then create a signed copy. Nothing is sent automatically.</p></div><button class="primary" data-action="new-letter">+ New letter</button></div>${comms.length?`<div class="letter-layout section-gap"><aside class="letter-menu" aria-label="Select a letter">${comms.map(c=>`<button data-action="open-letter" data-id="${attr(c.id)}" class="letter-item${c.id===S.commId?' active':''}"><strong>${esc(c.title||templateLabel(c.kind))}</strong><small>${esc(S.detail.parties.find(p=>p.id===c.party_id)?.name||'Whole case')}</small><small>${esc(dateText(c.date))} · ${esc(c.id)}</small></button>`).join('')}</aside><div id="letter-editor"></div></div>`:'<div class="empty"><h3>Start with a contact letter</h3><p>Choose a party and a template. Every draft can be edited before use.</p><button data-action="new-letter">Create a letter</button></div>'}</div>`;if(comms.length)renderLetterEditor();}
function savedReportingExports(c){if(c.delivery==='email')return '';return `<div class="saved-versions"><h3>Saved reporting exports</h3><p class="help">Exports are saved with this student’s case and remain available here. A signed final also generates an export automatically.</p>${(c.report_exports||[]).slice().reverse().map(item=>`<div class="version-row"><span>${esc(item.letter_status||'draft')} · ${esc(dateText(item.created))}${item.missing_fields?.length?' · '+esc(item.missing_fields.length)+' missing answers':''}</span><a href="${attr(safeLocal(item.url))}" download="${attr(item.download_name||(item.path||'report.json').split('/').pop())}">Download JSON</a></div>`).join('')||'<p class="help">No reporting exports yet.</p>'}</div>`;}
function renderLetterEditor(){const c=(S.detail.communications||[]).find(c=>c.id===S.commId);if(!c)return;if(c.uploaded_original){const original=(c.source_file_ids||[]).map(id=>S.detail.files.find(f=>f.id===id)).find(Boolean);$('#letter-editor').innerHTML=`<section class="official-outcome-original"><span class="badge">Official outcome PDF</span><h3 class="section-gap">Original outcome letter</h3><p class="help">The uploaded original is preserved. Open the PDF to review the issued letter.</p>${original?`<a class="button" href="${attr(safeLocal(original.url))}" target="_blank" rel="noopener">Open official outcome PDF ↗</a>`:'<p class="help">The original file is unavailable.</p>'}</section>`;return;}$('#letter-editor').innerHTML=`<form data-form="save-letter" data-dirty><div class="panel-head">${c.historical?`<div class="notice">${c.uploaded_original?'Official outcome letter preserved as the uploaded original PDF. Open the original below; it will not be regenerated or signed.':c.historical_external_author?'The original outcome has a different or unconfirmed author. Open its preserved source below; it will not be reissued under your name.':'Historical outcome preserved. Review the editable reconstruction only before reuse or signing a new copy.'}</div><div class="actions section-gap">${(c.source_file_ids||[]).map(id=>S.detail.files.find(f=>f.id===id)).filter(Boolean).map(f=>`<a href="${attr(safeLocal(f.url))}" target="_blank" rel="noopener">Open original ${esc((f.original_name||f.name).split('.').pop().toUpperCase())} ↗</a>`).join('')}</div>`:''}<span class="badge ${c.reviewed?'':'amber'}">${c.uploaded_original?'Official outcome PDF':c.historical?'Historical original preserved':c.reviewed?'Wording reviewed':'Wording needs review'}</span><span data-unsaved class="unsaved"></span></div><div class="input-guide section-gap"><span data-input-count role="status" aria-live="polite"></span><button type="button" data-action="next-input">Next field needing input</button><p class="help">Red markers identify blank fields to complete. Optional fields and explicit None selections are not flagged. Prefilled wording still needs review.</p></div>${outcomeControls(c)}${reportingControls(c)}<div class="grid two"><input type="hidden" name="title" value="${attr(c.title)}"><input type="hidden" name="date" value="${attr(dateInput(c.date))}"><input type="hidden" name="subject" value="${attr(c.subject)}">${c.deadline_business_days===5?`<div><label>Response deadline</label><input name="response_deadline_display" readonly value="${attr(deadlineText(c.response_deadline))}" data-deadline="${attr(c.response_deadline)}"><p class="help">Five business days after the send date; excludes weekends and published Rutgers closures. Change the send date if you send later. Calendar: 2026–2027.</p></div>`:''}<div class="span-all">${textarea('Recipient / address','recipient',c.recipient,'rows="2"')}</div>${c.delivery==='email'?'':`<div class="span-all">${field('Salutation','salutation',c.salutation||'Dear [STUDENT]:')}</div>`}<div class="span-all">${textarea('Letter body','body',c.body,'class="body-editor" spellcheck="true" required')}</div></div><p class="help">Template placeholders are shown in brackets. Check all names, dates, deadlines, factual statements, and procedural language.</p><label class="check section-gap"><input type="checkbox" name="reviewed"${checked(c.reviewed)}>I have reviewed and corrected this wording.</label><div class="actions section-gap"><button class="primary" type="submit">Save letter</button>${c.delivery==='email'?`<button type="button" data-action="email-letter">Prepare email</button><button type="button" data-action="copy-email">Copy email text</button><p class="help">Email draft — no closing signature is added. Nothing is sent automatically.</p>`:`<button type="button" data-action="preview-letter">Preview PDF</button><button type="button" data-action="sign-letter">Create signed final</button><button type="button" data-action="export-report">Export reporting JSON</button><button type="button" data-action="email-letter"${(c.revisions||[]).some(r=>r.kind==='signed'||r.kind==='final')?'':' disabled'}>Email signed letter</button>`}<button type="button" class="quiet" data-action="prepare-brief">Prepare AI handoff</button>${!c.historical&&!(c.revisions||[]).some(r=>['signed','final','historical original'].includes(r.kind))?`<button type="button" class="quiet" data-action="abandon-draft">Abandon draft</button>`:''}</div></form><div class="saved-versions"><h3>Saved PDF versions</h3>${(c.revisions||[]).slice().reverse().map(r=>`<div class="version-row"><span>${r.kind==='final'||r.kind==='signed'?'Signed final':r.kind==='historical original'?'Historical original':'Preview'} · ${esc(dateText(r.created))}</span><a href="${attr(safeLocal(r.url))}" target="_blank" rel="noopener">Open PDF ↗</a></div>`).join('')||'<p class="help">No PDF versions yet. Preview the letter when you are ready.</p>'}</div>${savedReportingExports(c)}${c.email_prepared_at?`<p class="help">${c.sent_at?'Sent date: '+esc(dateText(c.sent_at)):'Email prepared; sending not yet confirmed.'}</p><button data-action="confirm-email-sent">I sent this email</button>`:''}<button type="button" class="quiet section-gap" data-action="delete-letter">Delete letter and JSON</button>`;updateInputMarkers();}
function renderActivity(){const events=(S.detail.events||[]).slice().reverse();$('#case-content').innerHTML=`<div class="panel"><h2>Add a case note</h2><form data-form="add-event"><label class="sr-only" for="activity-note">Activity note</label><textarea id="activity-note" name="note" placeholder="Record a call, meeting, next action, or other update…" required></textarea><button class="primary section-gap" type="submit">Add note</button></form></div><div class="panel"><h2>Case history</h2><ul class="timeline">${events.map(e=>`<li><div>${esc(e.action||e.note||'Case updated')}</div><p class="help">${esc(dateText(e.at))}${e.at?` · ${esc(new Date(e.at).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}))}`:''}</p></li>`).join('')||'<li><p class="muted no-margin">Activity will appear here as you work.</p></li>'}</ul></div>`;}
function renderArchive(){const a=S.archive;$('#page').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Preserved materials</div><h1>Historical archive</h1><p>Find a historical case and open all of its associated materials.</p></div><button data-action="refresh-archive">Refresh list</button></div><div class="notice green">Case boundaries follow the original folders and matched decision copies. Open/closed status is being reviewed separately. Your complete original backup is preserved.</div><div class="archive-tools"><label class="sr-only" for="archive-search">Find an archived file</label><input id="archive-search" type="search" placeholder="Find a case, person, or file…" value="${attr(S.archiveSearch)}"><label class="sr-only" for="archive-filter">File category</label><select id="archive-filter"><option value="all">All categories</option>${[...new Set((a?.files||[]).map(f=>f.classification||'Other'))].sort().map(v=>`<option value="${attr(v)}"${selected(S.archiveFilter,v)}>${esc(pretty(v))}</option>`).join('')}</select></div><div class="panel"><div id="archive-results">${a?'':'<p class="muted">Loading the archive…</p>'}</div></div>`;if(a)renderArchiveResults();}
function renderArchiveResults(){const a=S.archive||{},files=(a.files||[]),q=S.archiveSearch.toLocaleLowerCase(),byId=new Map(files.map(f=>[f.id,f]));const groups=(a.groups||[]).map(g=>({...g,items:(g.files||[]).map(id=>byId.get(id)).filter(Boolean)})).filter(g=>(!g.items.length&&S.archiveFilter==='all'||g.items.some(f=>S.archiveFilter==='all'||f.classification===S.archiveFilter))&&(g.label.toLocaleLowerCase().includes(q)||g.id.toLocaleLowerCase().includes(q)||g.items.some(f=>String(f.path).toLocaleLowerCase().includes(q))));$('#archive-results').innerHTML=groups.length?`<p class="help">${groups.length} case or resource groups · ${files.length} preserved files</p>${groups.map(g=>`<details class="panel"><summary><strong>${esc(g.label)}</strong> <span class="badge gray">${g.items.length} files</span> ${g.case_id?`<span class="badge ${g.closed?'gray':'amber'}">${g.review?'Status not reviewed':g.closed?'Closed':'Open'}</span>`:''}</summary><div class="section-gap">${g.case_id?`<button class="primary" data-action="open-case" data-id="${attr(g.case_id)}">Open case ${esc(g.case_id)}</button>`:''}<div class="file-list section-gap">${g.items.map(f=>`<div class="file-row"><div class="file-description"><a href="${attr(safeLocal(f.url))}" target="_blank" rel="noopener">${esc(String(f.path).split('/').pop())} ↗</a><p class="help">${esc(pretty(f.classification||'Other'))} · ${esc(sizeText(f.bytes))}</p></div></div>`).join('')}</div></div></details>`).join('')}`:'<div class="empty compact">No case or resource groups match this view.</div>';}

function renderGuidance(){$('#page').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Procedures and reference</div><h1>RU Guidance</h1><p>Rutgers resources for your work as an Academic Integrity Facilitator.</p></div></div><div class="notice">Check current official policy and the facts of the case before using a template. Checklist completion records your work; it does not establish a finding.</div><div class="guidance-grid">${(S.boot.guidance||[]).map(g=>`<article class="panel guidance-card"><h2>${esc(g.title)}</h2><p>${esc(g.note||'Official Rutgers resource.')}</p><a href="${attr(safeWeb(g.url))}" target="_blank" rel="noopener">Open resource ↗</a></article>`).join('')||'<div class="panel"><p class="muted">No reference links have been configured yet.</p></div>'}</div>`;}
function renderTemplates(){
  const data=S.templateReview;
  if(!data){$('#page').innerHTML='<div class="page-heading"><div><h1>Templates</h1><p>Loading your local template wording…</p></div></div>';return;}
  const source=S.templateSelection.startsWith('source:')?(data.sources||[]).find(x=>x.id===S.templateSelection.slice(7)):null;
  const saved=S.templateSelection.startsWith('template:')?(data.templates||[]).find(x=>x.id===S.templateSelection.slice(9)):null;
  const value=saved||source||{};
  $('#page').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Reusable correspondence</div><h1>Templates</h1><p>Review your existing wording once, then use it as a starting point for future letters.</p></div><button data-action="choose-template" data-id="">+ Blank template</button></div><div class="case-layout"><aside class="panel"><h2>Reviewed templates</h2><div class="letter-menu">${(data.templates||[]).map(x=>`<button class="letter-item${saved?.id===x.id?' active':''}" data-action="choose-template" data-id="template:${attr(x.id)}"><strong>${esc(x.label)}</strong><small>Available for new letters</small></button>`).join('')||'<p class="help">Templates you approve will appear here.</p>'}</div></aside><section><div class="panel"><div class="panel-head"><h2>${saved?'Edit reviewed template':source?'Clean up source wording':'Write a reusable template'}</h2><span class="unsaved" data-unsaved></span></div>${source?`<div class="notice">This is source material. It may be a filled historical letter. Remove previous recipients, identifiers, dates, findings, and sanctions that should vary by case.${(source.flags||[]).length?`<p class="help section-gap">${source.flags.map(esc).join('<br>')}</p>`:''}</div><details><summary>View original source wording</summary>${source.source_url?`<p class="section-gap"><a href="${attr(safeLocal(source.source_url))}" target="_blank" rel="noopener">Open original document ↗</a></p>`:''}<textarea class="extract-text section-gap" readonly aria-label="Original source wording">${esc(source.body||'')}</textarea></details>`:''}<form data-form="save-template" data-dirty class="section-gap"><input type="hidden" name="id" value="${attr(saved?.id||'')}"><input type="hidden" name="source_id" value="${attr(source?.id||saved?.source_id||'')}"><div class="field">${field('Template name','label',value.label||'','text','required placeholder="Contact letter — meeting invitation"')}</div>${textarea('Reusable wording','body',value.body||'','class="body-editor" required')}<p class="help">Use placeholders such as [STUDENT], [RUID], [EMAIL], [CASE], and [COURSE]. Keep details that require confirmation clearly marked in brackets. Creating a template does not create a letter.</p><label class="check section-gap"><input type="checkbox" name="approved" required>I removed old student details and reviewed this reusable wording.</label><div class="actions section-gap"><button class="primary" type="submit">Save reviewed template</button></div></form></div></section></div>`;
}
function renderSettings(){const settings=S.boot.settings||{};const sender=settings.sender||{};const contact=Array.isArray(sender.contact_lines)?sender.contact_lines.join('\n'):sender.contact_lines||'';$('#page').innerHTML=`<div class="settings-wrap"><div class="page-heading"><div><div class="eyebrow">Your correspondence</div><h1>Settings</h1><p>Shared details used on your local letterhead.</p></div><span data-unsaved class="unsaved"></span></div><div class="panel"><h2>Letterhead and signature</h2><form data-form="settings" data-dirty><div class="grid settings-letterhead-grid">${field('Your name','sender_name',sender.name)}${field('Role / title','sender_title',sender.title)}${field('Department','sender_department',sender.department)}<div class="span-all">${textarea('Contact lines','contact_lines',contact,'rows="4"')}</div><div class="span-all settings-signature-field"><label for="shared-integrity-signature">Signature image</label><div class="settings-path-row"><input id="shared-integrity-signature" name="signature_file" value="${attr(settings.signature_file||'')}"><button type="button" hidden data-browse-signature>Browse…</button></div><span class="field-help">Shared with Recommendations</span><span class="field-help" role="status" data-signature-status></span></div></div><div class="actions section-gap"><button class="primary" type="submit">Save settings</button></div></form></div></div>`;}
async function openCase(id){if(!await leaveDraft())return;const data=await api(`/api/cases/${encodeURIComponent(id)}`);S.detail=data.case||data;S.commId=null;S.meetingId=undefined;S.tab='overview';S.filter=S.detail.status_review?'review':S.detail.closed?'closed':'open';S.view='cases';render();}
async function acceptCase(data,message='Saved.'){S.detail=data.case||data;S.cases=(await api('/api/cases')).cases||[];if(['open','closed'].includes(S.filter))S.filter=S.detail.closed?'closed':'open';markDirty(false);renderCases();if(message)toast(message);}
async function newCaseDialog(){if(!await leaveDraft())return;modal('Start a new case',`<form id="new-case-form" data-form="new-case"><p class="help">One student per case. Upload the incident report to extract details. If it lists several students, you will choose the student for this case.</p><label>Incident report (optional)</label><input type="file" name="incident_report" accept=".pdf,application/pdf"><div class="grid two">${field('Semester (optional)','semester','','text','placeholder="Fall 2026"')}${field('Course number (optional)','course','','text','placeholder="135"')}</div></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="new-case-form">Create case</button>');}
async function partyDialog(id){if(!await leaveDraft())return;const p=S.detail.parties.find(p=>p.id===id)||{};modal(id?'Edit student':'Add student',`<form id="party-form" data-form="save-party" data-party="${attr(id||'')}"><p class="help">Enter confirmed details from the referral or roster. Identifiers remain local.</p><div class="grid two section-gap">${field('First / given name(s)','first_name',p.first_name||'','text','required')}${field('Last / family name(s)','last_name',p.last_name||'','text','required')}<div class="span-all"><p class="help">Letters and reporting forms use given name(s) followed by family name(s). Keep compound names together in the appropriate field.${!p.first_name&&p.name?' Current full name: '+esc(p.name):''}</p></div>${field('RUID','ruid',p.ruid,'text','inputmode="numeric"')}${field('NetID','netid',p.netid)}${field('Email','email',p.email,'email')}<div class="span-all">${textarea('Party notes','notes',p.notes)}</div></div></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="party-form">Save student</button>');}
async function stepDialog(){if(!await leaveDraft())return;modal('Add a checklist step',`<form id="step-form" data-form="add-step"><div class="grid">${field('Step','label','','text','required placeholder="Describe the action to complete"')}<div><label for="step-party">Applies to</label><select id="step-party" name="party_id">${partyOptions()}</select></div></div></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="step-form">Add step</button>');}
async function letterDialog(){if(!await leaveDraft())return;if(!S.detail.parties.length){toast('Add student in Overview before creating their letter.');return;}const templates=S.boot.templates?.length?S.boot.templates:[{id:'contact',label:'Contact / meeting invitation'},{id:'meeting',label:'Meeting follow-up'},{id:'outcome',label:'Outcome letter'},{id:'appeal',label:'Appeal response'},{id:'general',label:'General correspondence'}];modal('Create a letter',`<form id="letter-form" data-form="new-letter"><div class="grid"><div><label for="letter-kind">Start with a template</label><select id="letter-kind" name="kind">${templates.map(t=>`<option value="${attr(t.id)}">${esc(t.label)}</option>`).join('')}</select></div><input type="hidden" name="party_id" required value="${attr(S.detail.parties[0].id)}"><p>For ${esc(S.detail.parties[0].name)}</p>${field('Assessment','assessment',assessmentValue(S.detail.assessment),'text','placeholder="Final Exam"')}${field('Send / letter date','date',localToday(),'date','required')}${field('Letter title','title','','text','placeholder="Leave blank to use the template name"')}</div><p class="help section-gap">The template is a starting point. Review procedural requirements and every factual statement before signing.</p></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="letter-form">Create draft</button>');}
function formObject(form){return Object.fromEntries(new FormData(form).entries());}
async function saveLetter(silent=false,compose=false){const form=$('form[data-form="save-letter"]');if(!form||!form.reportValidity())return false;const payload=formObject(form);payload.reviewed=form.elements.reviewed.checked;const reporting=reportingChoices(form);if(reporting)payload.reporting=reporting;const choices=outcomeChoices(form);if(choices){payload.outcome_choices=choices;payload.compose_outcome=compose;}const data=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}`,payload);S.detail=data.case||data;markDirty(false);if(!silent){renderCaseDetail();toast('Letter saved.');}return true;}
async function previewLetter(){if(!await saveLetter(true))return;const result=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/build`,{final:false});S.detail=(await api(casePath())).case;renderCaseDetail();showPdf(result.url,'Preview ready','This is an unsigned preview. Check the wording and layout before creating a signed final.');}
function showPdf(url,title,note){if(!url)throw new Error('The PDF was built, but no file link was returned. Reopen the letter to see saved versions.');modal(title,`<p>${esc(note)}</p><a class="primary" href="${attr(safeLocal(url))}" target="_blank" rel="noopener">Open PDF ↗</a>`,'<button class="primary" data-action="close-modal">Done</button>');}
async function signDialog(){if(!await saveLetter(true))return;renderCaseDetail();const comm=S.detail.communications.find(c=>c.id===S.commId);if(!comm.reviewed){toast('Review the wording and check the review box before signing.',true);return;}modal('Approve the signed final',`<form id="sign-form" data-form="sign-letter"><p>This creates a PDF using your letterhead and signature, and saves it with this case.</p><p class="notice">Check the preview first. Confirm the current recipient and student information, dates, factual statements, and the applicable procedure.</p><label class="check"><input type="checkbox" name="approved" required>I approve this letter and authorize adding my signature.</label><p class="help section-gap">Nothing will be emailed or submitted.</p></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="sign-form">Create signed final</button>');}
async function extractFile(id){if(!await leaveDraft())return;toast('Extracting text locally…');const data=await api(`${casePath()}/extract`,{file_id:id});const f=S.detail.files.find(f=>f.id===id);const p=S.detail.parties.find(p=>p.id===f?.party_id)||{};const candidate=key=>{const v=data.candidates?.[key];return typeof v==='string'?v:Array.isArray(v)?v[0]||'':v?.value||'';};modal('Review extracted details',`<form id="extract-form" data-form="extract-party"><p class="help">Suggestions are not saved automatically. Confirm each value against the source before adding or updating a party.</p>${(data.warnings||[]).length?`<div class="notice section-gap">${data.warnings.map(esc).join('<br>')}</div>`:''}<div class="grid two section-gap"><div class="span-all"><label for="extract-target">Save to</label><select id="extract-target" name="target"><option value="">New party</option>${S.detail.parties.map(x=>`<option value="${attr(x.id)}"${selected(p.id,x.id)}>${esc(personName(x))}</option>`).join('')}</select></div><div class="span-all">${field('Full name','name',p.name||candidate('name'),'text','required')}</div>${field('RUID','ruid',p.ruid||candidate('ruid'))}${field('NetID','netid',p.netid||candidate('netid'))}${field('Email','email',p.email||candidate('email'),'email')}<div><label for="extract-role">Role</label><select id="extract-role" name="role">${['student','instructor','other'].map(v=>`<option value="${v}"${selected(p.role||'student',v)}>${pretty(v)}</option>`).join('')}</select></div><div class="span-all">${textarea('Party notes','notes',p.notes)}</div></div><details class="section-gap"><summary>View locally extracted text</summary><textarea class="extract-text section-gap" readonly aria-label="Extracted source text">${esc(data.text||'No readable text was found.')}</textarea></details></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="extract-form">Confirm and save party</button>',true);}
async function briefDialog(){if(!await saveLetter(true))return;renderCaseDetail();const result=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/brief`,{approved:false});S.brief={commId:S.commId};modal('Review the AI handoff',`<form id="brief-form" data-form="approve-brief"><div class="notice">Review the exact text below and remove identifying or sensitive details you do not want shared. No original files are authorized unless you explicitly select and approve them below.</div>${(result.warnings||[]).length?`<p class="help">${result.warnings.map(esc).join('<br>')}</p>`:''}<label for="brief-text">Anonymized brief</label><textarea class="brief" id="brief-text" name="text" required>${esc(result.text||'')}</textarea>${S.detail.files.length?`<details class="section-gap"><summary>Authorize selected supporting files (optional)</summary><p class="help section-gap">Your chat can read these files only if you select them and grant permission. They may contain private names or other sensitive information. The receipt records the exact file and its hash.</p><div class="file-list">${S.detail.files.map(f=>`<label class="check section-gap"><input type="checkbox" name="attachment_ids" value="${attr(f.id)}">${esc(f.name)}</label>`).join('')}</div><label class="check section-gap"><input type="checkbox" name="attachment_permission">I explicitly authorize this chat to read the selected original files for this letter.</label></details>`:''}<label class="check section-gap"><input type="checkbox" name="approved" required>I have reviewed this brief and approve this text for the handoff.</label></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" form="brief-form" type="submit">Approve and prepare handoff</button>',true);}
async function showArchive(){S.view='archive';render();if(!S.archive){S.archive=await api('/api/archive');renderArchive();}}
function putSavedRationale(source){const form=$('form[data-form="save-letter"]');const input=form?.elements.outcome_rationale;if(!input)return;if(input.value.trim()){toast('Your existing rationale was kept. Clear that field first if you want to replace it.',true);return;}input.value=source.text;form.elements.rationale_file_id.value=source.file_id;form.elements.reviewed.checked=false;markDirty();toast('Saved rationale copied. Review it, then build the letter from selections.');}
async function chooseSavedRationale(){const c=S.detail.communications.find(x=>x.id===S.commId);const input=$('form[data-form="save-letter"]')?.elements.outcome_rationale;if(input?.value.trim()){toast('Your existing rationale was kept. Clear that field first if you want to replace it.',true);return;}const data=await api(`${casePath()}/rationales?party_id=${encodeURIComponent(c.party_id)}`);S.rationaleCandidates=data.rationales;if(!data.rationales.length){toast('No saved finding-rationale text is linked to this student.',true);return;}if(data.rationales.length===1){putSavedRationale(data.rationales[0]);return;}modal('Choose a saved rationale',`<form id="rationale-form" data-form="choose-rationale"><label>Evidence file</label><select name="rationale_choice" id="rationale-choice">${data.rationales.map(x=>`<option value="${attr(x.file_id)}">${esc(x.name)}</option>`).join('')}</select><label>Preview</label><textarea id="rationale-preview" rows="12" readonly>${esc(data.rationales[0].text)}</textarea></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="rationale-form">Use this rationale</button>',true);}
async function runAction(el){const action=el.dataset.action;if(action==='meeting-response'){await meetingResponseDialog();return;}if(action.startsWith('handoff-')||action==='rationale-handoff'){await handoffAction(el);return;}if(action==='reclassify-evidence'){const f=S.detail.files.find(f=>f.id===el.dataset.id);if(!f)return;modal('Change evidence category',`<p>${esc(f.name)}</p><form id="evidence-category-form" data-form="evidence-category" data-id="${attr(f.id)}"><label for="evidence-category">Document category</label><select id="evidence-category" name="kind">${EVIDENCE_TYPES.map(([id,label])=>`<option value="${id}"${selected(id,f.kind)}>${esc(label)}</option>`).join('')}</select><p class="help">Supporting evidence includes photos, screenshots, Canvas reports, logs, and other supporting records. Changing category preserves the file and case details. For an incident report, use Extract report details afterward.</p></form>`,'<button data-action="close-modal">Cancel</button><button class="primary" type="submit" form="evidence-category-form">Save category</button>');return;}if(action==='delete-evidence'){const f=S.detail.files.find(f=>f.id===el.dataset.id);if(!f)return;if(!await window.GWorksDialogs.confirm('Delete '+f.name+' from this case’s Evidence list? A recovery copy is retained. Existing case details and checklist dates will remain.'))return;await acceptCase(await api(`${casePath()}/files/${encodeURIComponent(f.id)}`,{action:'delete',confirmed:true}),'Evidence deleted.');return;}if(action==='review-contacts'){await contactDialog();return;}if(action==='email-letter'){await emailLetterDialog();return;}if(action==='toggle-case-status'){if(!await leaveDraft())return;await acceptCase(await api(casePath(),{closed:!S.detail.closed,status_review:false}),S.detail.closed?'Case reopened.':'Case closed.');return;}if(action==='skip-step'){await acceptCase(await api(`${casePath()}/steps`,{id:el.dataset.stepId,done:false,skipped:el.dataset.skipped!=='true'}),'Checklist updated.');return;}if(action==='edit-step-date'){editStepDateDialog(el.dataset.stepId);return;}if(action==='upload-report'){if(!await leaveDraft())return;S.tab='evidence';renderCaseDetail();$('#upload-kind').value='incident-report';$('#upload-file').focus();return;}if(action==='review-intake'){await intakeDialog(await api(`${casePath()}/intake`,{file_id:el.dataset.id}));return;}if(action==='new-meeting'){if(S.dirty)await saveMeeting();S.meetingId='';renderMeetings();return;}if(action==='open-meeting'){if(S.dirty)await saveMeeting();S.meetingId=el.dataset.id;renderMeetings();return;}if(action==='complete-meeting'){await saveMeeting(true);return;}if(action==='confirm-email-sent'){if(!await window.GWorksDialogs.confirm('Confirm that you sent this email in Thunderbird. The relevant checklist item will be completed with today’s date.'))return;const sent=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/email-sent`,{confirmed:true,sent_date:localToday()});closeModal();await acceptCase(sent,'Sent date recorded; checklist updated.');return;}if(action==='open-thunderbird'){await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/email-open`,{confirmed:true,fingerprint:S.emailPlan.fingerprint});S.detail=(await api(casePath())).case;renderCaseDetail();modal('Finish sending in Thunderbird','<p>Your unsent email is ready in Thunderbird. After you send it, confirm below to complete the checklist and record today’s date.</p>','<button data-action="close-modal">I will confirm later</button><button class="primary" data-action="confirm-email-sent">I sent this email</button>');return;}if(action==='next-input'){nextMissingInput();return;}if(action==='add-academic'){const selected=$$('[data-academic-sanction]').filter(x=>x.value);if(selected.length&&!await window.GWorksDialogs.confirm('Academic sanctions can overlap or contradict each other. Add another academic sanction anyway?'))return;$('#academic-sanctions').insertAdjacentHTML('beforeend',academicSanctionRow({},selected.length>0));$('[data-academic-decision]').value='add';$('[data-academic-container]').hidden=false;markDirty();return;}if(action==='remove-academic'){el.closest('[data-academic-row]').remove();if(!$$('[data-academic-row]').length){$('[data-academic-decision]').value='';$('[data-academic-container]').hidden=true;}markDirty();return;}if(action==='delete-letter'){if(!await window.GWorksDialogs.confirm('Delete this letter and all its generated PDF and reporting JSON files? Original evidence is kept. A recovery copy will be retained.'))return;const data=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/delete`,{confirmed:true});S.commId=null;await acceptCase(data,'Letter and generated files deleted.');return;}if(action==='abandon-draft'){if(!await window.GWorksDialogs.confirm('Abandon and delete this unsigned draft? The case, evidence, and historical or signed letters will be kept.'))return;const data=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/abandon`,{});S.commId=null;await acceptCase(data,'Draft abandoned. Case and evidence kept.');return;}if(action==='load-rationale'){await chooseSavedRationale();return;}if(action==='close-modal'){closeModal();return;}if(action==='nav'){if(!await leaveDraft())return;if(el.dataset.view==='archive'){await showArchive();return;}if(el.dataset.view==='templates'){S.view='templates';render();if(!S.templateReview){S.templateReview=await api('/api/template-review');renderTemplates();}return;}S.view=el.dataset.view;render();return;}if(action==='choose-template'){if(!await leaveDraft())return;S.templateSelection=el.dataset.id||'';renderTemplates();return;}if(action==='new-case'){await newCaseDialog();return;}if(action==='open-case'){await openCase(el.dataset.id);return;}if(action==='tab'){if(!await leaveDraft())return;S.tab=el.dataset.tab;renderCaseDetail();return;}if(action==='add-party'){await partyDialog();return;}if(action==='edit-party'){await partyDialog(el.dataset.id);return;}if(action==='add-step'){await stepDialog();return;}if(action==='new-letter'){await letterDialog();return;}if(action==='open-letter'){if(!await leaveDraft())return;S.commId=el.dataset.id;renderLetters();return;}if(action==='preview-letter'){await previewLetter();return;}if(action==='sign-letter'){await signDialog();return;}if(action==='export-report'){if(!await saveLetter(true))return;const item=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/report`,{});S.detail=(await api(casePath())).case;renderCaseDetail();modal('Reporting export ready',`<p>This file is for the Chrome helper. It does not submit a form.</p><p><a href="${attr(safeLocal(item.url))}" download="${attr(item.download_name||(item.path||'report.json').split('/').pop())}">Download reporting JSON</a></p>${item.missing_fields.length?`<h3>Missing answers</h3><ul>${item.missing_fields.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}${item.warnings.length?`<ul>${item.warnings.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}`,'<button data-action="close-modal">Done</button>');return;}if(action==='add-violation'){$('#violation-rows').insertAdjacentHTML('beforeend',violationRow());markDirty();return;}if(action==='compose-outcome'){if(!await saveLetter(true,true))return;renderCaseDetail();toast('Letter rebuilt from your selections. Review the wording before signing.');return;}if(action==='copy-email'){if(!await saveLetter(true))return;const c=S.detail.communications.find(x=>x.id===S.commId);await navigator.clipboard.writeText(c.body);renderCaseDetail();toast('Email body copied. Copy the subject separately into your email.');return;}if(action==='prepare-brief'){await briefDialog();return;}if(action==='extract'){await extractFile(el.dataset.id);return;}if(action==='refresh-archive'){S.archive=await api('/api/archive');renderArchive();toast('Archive list refreshed.');return;}if(action==='local-ai-draft'||action==='redacted-online-ai'){const approved=S.approvedAIBrief;if(!approved)throw new Error('Prepare and approve a drafting brief first.');await LocalDrafting.open({...approved,mode:action==='local-ai-draft'?'general':'online',token:S.boot.token,onApplied:async()=>{closeModal();if(S.detail?.id===approved.target.caseId)await acceptCase(await api(casePath()),'Local draft saved. Review it before signing or sending.');}});return;}if(action==='copy-handoff'){await navigator.clipboard.writeText($('#handoff-text').value);toast('Handoff instructions copied.');return;}}
async function submitForm(form){const type=form.dataset.form;if(type==='meeting-response'){const values=formObject(form);values.confirmed_no_response=form.elements.confirmed_no_response.checked;const data=await api(`${casePath()}/meeting-response`,values);closeModal();await acceptCase(data,'Student response saved.');return;}if(type==='evidence-category'){const data=await api(`${casePath()}/files/${encodeURIComponent(form.dataset.id)}`,{action:'reclassify',kind:form.elements.kind.value});closeModal();await acceptCase(data,'Evidence category updated.');return;}if(type==='save-meeting'){await saveMeeting();return;}if(type==='step-date'){const data=await api(`${casePath()}/steps`,{id:form.dataset.stepId,edit_date:true,completed_date:form.elements.completed_date.value});closeModal();await acceptCase(data,'Checklist date updated.');return;}if(type==='apply-intake'){const data=await api(`${casePath()}/intake`,{file_id:S.intakeSource,ruid:form.elements.ruid.value,apply:true,overwrite:form.elements.overwrite.checked});closeModal();await acceptCase(data,'Report details added. Check missing fields in Overview.');return;}const values=formObject(form);if(type==='case-contacts'){values.source_file_ids=S.contactReviewSources||[];const data=await api(`${casePath()}/contacts`,values);closeModal();await acceptCase(data,'Complainant and instructor confirmed.');return;}if(type==='choose-rationale'){const source=S.rationaleCandidates?.find(x=>x.file_id===values.rationale_choice);if(!source)throw new Error('Choose a saved rationale.');closeModal();putSavedRationale(source);return;}if(type==='new-case'){const file=form.elements.incident_report?.files?.[0];if(file&&file.size>50*1024*1024)throw new Error('Choose a PDF smaller than 50 MB.');if(!values.title)values.title='New case';delete values.incident_report;const data=await api('/api/cases',values);closeModal();S.view='cases';S.tab='overview';await acceptCase(data,'Case created.');if(file){const query=new URLSearchParams({name:file.name,kind:'incident-report'});const response=await fetch(`${casePath()}/files?${query}`,{method:'POST',headers:{'X-App-Token':S.boot.token,'Content-Type':'application/octet-stream'},body:file});const uploaded=await response.json();if(!response.ok)throw new Error(uploaded.error||'The report could not be uploaded.');await acceptCase(uploaded,'Incident report saved.');if(uploaded.intake_review)await intakeDialog(uploaded.intake_review);}return;}if(type==='save-case'){await acceptCase(await api(casePath(),values),'Case details saved.');return;}if(type==='save-party'){const path=form.dataset.party?`${casePath()}/parties/${encodeURIComponent(form.dataset.party)}`:`${casePath()}/parties`;const data=await api(path,values);closeModal();await acceptCase(data,'Party details saved.');return;}if(type==='add-step'){const data=await api(`${casePath()}/steps`,values);closeModal();await acceptCase(data,'Checklist step added.');return;}if(type==='add-event'){await acceptCase(await api(`${casePath()}/events`,values),'Case note added.');return;}if(type==='new-letter'){if(!values.title)values.title=templateLabel(values.kind);const data=await api(`${casePath()}/communications`,values);closeModal();S.tab='letters';S.commId=(data.case||data).communications?.slice(-1)[0]?.id||null;await acceptCase(data,'Draft created. Review and edit it before use.');return;}if(type==='save-letter'){await saveLetter();return;}if(type==='upload'){const file=form.elements.file.files[0];if(!file)throw new Error('Choose a file to upload.');if(file.size>50*1024*1024)throw new Error('Choose a file smaller than 50 MB.');const query=new URLSearchParams({name:file.name,kind:values.kind||'other'});const response=await fetch(`${casePath()}/files?${query}`,{method:'POST',headers:{'X-App-Token':S.boot.token,'Content-Type':'application/octet-stream'},body:file});const data=await response.json();if(!response.ok)throw new Error(data.error||'The file could not be uploaded.');await acceptCase(data,'Material saved locally.');if(data.intake_review)await intakeDialog(data.intake_review);else if(data.contact_review)await contactDialog(data.contact_review);if(data.intake_warning)toast(data.intake_warning,true);return;}if(type==='extract-party'){const target=values.target;delete values.target;const data=await api(target?`${casePath()}/parties/${encodeURIComponent(target)}`:`${casePath()}/parties`,values);closeModal();await acceptCase(data,'Confirmed details saved.');return;}if(type==='sign-letter'){if(!form.elements.approved.checked)return;closeModal();const result=await api(`${casePath()}/communications/${encodeURIComponent(S.commId)}/build`,{final:true,approved:true});S.detail=(await api(casePath())).case;renderCaseDetail();showPdf(result.url,'Signed final saved','Your signed PDF is saved with the case. You can open it below and send it through your usual approved channel.');return;}if(type==='approve-brief'){if(!form.elements.approved.checked)return;const attachmentIds=new FormData(form).getAll('attachment_ids');if(attachmentIds.length&&!form.elements.attachment_permission?.checked)throw new Error('Approve access to the selected files, or unselect them.');const result=await api(`${casePath()}/communications/${encodeURIComponent(S.brief.commId)}/brief`,{approved:true,text:values.text,attachment_ids:attachmentIds});const instructions=result.instructions||result.handoff||result.text||result.path||'The approved brief has been saved locally.';S.approvedAIBrief={brief:result.path.split(/[\\/]/).pop(),target:{caseId:S.detail.id,communicationId:S.brief.commId}};closeModal();modal('Your handoff is ready',`<p>Copy these instructions into your chat. They identify the approved local brief and any original files you explicitly authorized. No other case records may be read.</p><label for="handoff-text">Instructions to give the chat</label><textarea class="brief" id="handoff-text" readonly>${esc(instructions)}</textarea>${result.url?`<p class="section-gap"><a href="${attr(safeLocal(result.url))}" target="_blank" rel="noopener">Open approved brief ↗</a></p>`:''}`,'<button data-action="close-modal">Done</button><button class="primary" data-action="copy-handoff">Copy instructions</button><button class="primary" data-action="local-ai-draft">Draft with General AI</button><button data-action="redacted-online-ai">Redacted online handoff</button>',true);return;}if(type==='save-template'){if(!form.elements.approved.checked)throw new Error('Confirm that old student details were removed and the wording was reviewed.');const payload={label:values.label,body:values.body,source_id:values.source_id||'',approved:true};if(values.id)payload.id=values.id;const result=await api('/api/templates',payload);const saved=(result.templates||[]).slice().reverse().find(t=>t.label===trim(values.label)&&t.body===trim(values.body));S.boot=await api('/api/bootstrap');S.templateReview=await api('/api/template-review');S.templateSelection=saved?'template:'+saved.id:S.templateSelection;markDirty(false);renderTemplates();toast('Reviewed template saved. It is now available when creating a letter.');return;}if(type==='settings'){const sender={name:values.sender_name,title:values.sender_title,department:values.sender_department,contact_lines:values.contact_lines.split('\n').map(trim).filter(Boolean)};const data=await api('/api/settings',{sender,signature_file:values.signature_file,signature_changed:values.signature_file!==(S.boot.settings?.signature_file||'')});S.boot.settings=data.settings||data;markDirty(false);renderSettings();toast('Letter settings saved.');return;}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(S.busy)return;S.busy=true;el.disabled=true;Promise.resolve(runAction(el)).catch(error=>toast(errorText(error),true)).finally(()=>{S.busy=false;if(el.isConnected)el.disabled=false;});});
document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(S.busy)return;S.busy=true;const buttons=$$('button[type=submit]',form);buttons.forEach(b=>b.disabled=true);Promise.resolve(submitForm(form)).catch(error=>toast(errorText(error),true)).finally(()=>{S.busy=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});});});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('form[data-form="save-meeting"]')){markDirty();clearTimeout(meetingTimer);meetingTimer=setTimeout(()=>saveMeeting().catch(error=>toast(errorText(error),true)),1200);return;}if(el.id==='case-search'){S.search=el.value;renderCaseList();return;}if(el.id==='archive-search'){S.archiveSearch=el.value;renderArchiveResults();return;}if(el.name==='date'&&el.closest('form[data-form="save-letter"]'))updateEmailDeadline(el.closest('form'));if(el.name==='outcome_assessment'&&el.value.trim()&&!/\[[A-Z _-]+\]/.test(el.value)){const form=el.closest('form[data-form="save-letter"]');const letter=S.detail?.communications?.find(x=>x.id===S.commId);if(letter?.outcome_kind==='not-responsible'&&form?.elements.body)form.elements.body.value=form.elements.body.value.replaceAll('[ASSESSMENT]',el.value.trim());}if(el.closest('[data-dirty]')){markDirty();if(el.closest('form[data-form="save-letter"]')&&el.name!=='reviewed'){const review=$('form[data-form="save-letter"] input[name="reviewed"]');if(review)review.checked=false;}}});
document.addEventListener('change',event=>{(async()=>{const el=event.target;if(el.id==='response-status'){responseFields(el.form);return;}if(el.id==='overview-instructor-relationship'&&el.value==='same'){const form=el.closest('form');form.elements.instructor_name.value=form.elements.complainant_name.value;form.elements.instructor_email.value=form.elements.complainant_email.value;markDirty();return;}if(el.id==='instructor-relationship'){const box=$('[data-instructor-fields]');box.hidden=el.value!=='different';for(const input of $$('input',box)){input.disabled=el.value!=='different';input.required=el.value==='different';}return;}if(el.hasAttribute('data-academic-decision')){$('[data-academic-container]').hidden=el.value!=='add';if(el.value==='add'&&!$$('[data-academic-row]').length)$('#academic-sanctions').insertAdjacentHTML('beforeend',academicSanctionRow());markDirty();return;}if(el.dataset.sanctionSingle){refreshSanctionParameters(el.closest('[data-sanction-group]'),el.value);markDirty();return;}if(el.hasAttribute('data-academic-sanction')){await academicSelectionChanged(el);return;}if(el.hasAttribute('data-probation-mode')){for(const part of $$('[data-probation-part]',el.closest('[data-sanction-params]')))part.hidden=part.dataset.probationPart===(el.value==='date'?'semester':'date');markDirty();return;}if(el.id==='rationale-choice'){const source=S.rationaleCandidates?.find(x=>x.file_id===el.value);if(source)$('#rationale-preview').value=source.text;return;}if(el.id==='case-sort'){S.caseSort=el.value;renderCaseList();return;}if(el.id==='case-filter'){S.filter=el.value;renderCaseList();return;}if(el.id==='archive-filter'){S.archiveFilter=el.value;renderArchiveResults();return;}if(el.dataset.step){if(S.busy||!await leaveDraft()){el.checked=!el.checked;return;}S.busy=true;el.disabled=true;api(`${casePath()}/steps`,{id:el.dataset.step,party_id:el.dataset.party||'',done:el.checked}).then(data=>acceptCase(data,'Checklist updated.')).catch(error=>{el.checked=!el.checked;toast(errorText(error),true);}).finally(()=>{S.busy=false;if(el.isConnected)el.disabled=false;});return;}if(el.closest('[data-dirty]'))markDirty();})().catch(error=>toast(errorText(error),true));});
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
async function start(){try{S.boot=await api('/api/bootstrap');S.cases=(await api('/api/cases')).cases||[];render();}catch(error){$('#app').innerHTML=`<div class="loading"><div class="brand-mark">AI</div><h1>The casebook could not open</h1><p>${esc(errorText(error))}</p><button data-action="reload">Try again</button></div>`;$('[data-action="reload"]').addEventListener('click',()=>location.reload());}}
start();

// All extraction and redaction is performed by the local server. No model calls.
let RH=null;
function handoffSelect(){modal('Prepare a local rationale handoff',`<p>Choose evidence to include. Names, known identifiers, email addresses and nine-digit IDs are replaced in extracted text locally. Review every page and the text before exporting. Nothing is sent.</p><div id="handoff-selection">${S.detail.files.map(f=>`<label class="handoff-choice"><input type="checkbox" data-handoff-file value="${attr(f.id)}"> ${esc(f.name)}</label>`).join('')}</div><label class="handoff-choice"><input type="checkbox" id="handoff-meetings" checked> Include saved meeting notes</label><label class="handoff-choice"><input type="checkbox" id="handoff-case-notes"> Include case notes</label><p class="help">Supported: PDF, PNG/JPEG/WebP, TXT, CSV and DOCX. Other formats must be converted locally first. Original filenames and identity keys are excluded from the ZIP. Dates, handwriting and indirect identifiers still need your review.</p>`,'<button data-action="close-modal">Cancel</button><button class="primary" data-action="handoff-prepare">Prepare locally</button>',true);}
function handoffReviewUI(){modal('Review anonymized rationale handoff',`${RH.recovered_text?'<p class="notice">Saved redaction boxes and prepared copies were recovered. Text was rebuilt from the selected evidence; review it again and add any meeting notes or edits you need.</p>':''}<p>Review and edit the text, including names of other people and identifying context. For each PDF or image, review its pages and prepare a clean copy. If there are no identifiers, choose No redaction needed. Open and approve each prepared copy.</p><label for="handoff-text">Anonymized text</label><textarea id="handoff-text" rows="14">${esc(RH.text)}</textarea><div class="handoff-documents">${RH.files.filter(f=>f.pages).map(f=>`<section class="section-gap"><h3>${esc(f.label)} · ${f.pages} page(s)</h3><button data-action="handoff-redact" data-id="${attr(f.id)}">Review and redact pages</button><span id="handoff-status-${attr(f.id)}">${RH.reviews[f.id]?' Clean copy prepared':''}</span>${RH.reviews[f.id]?`<p><a href="${attr(RH.reviews[f.id].url)}" target="_blank" rel="noopener">Open prepared copy</a></p><label><input type="checkbox" data-handoff-approved="${attr(f.id)}"${RH.approved[f.id]?' checked':''}> I checked every page of this prepared copy; no identifying information remains.</label>`:''}</section>`).join('')}</div><label class="handoff-choice"><input type="checkbox" id="handoff-text-approved"> I reviewed the edited text and all included copies. I approve this package for sharing.</label><p class="help">Original documents and the local identity key are never included. Exporting saves a ZIP locally; you decide whether to share it.</p>`,'<button data-action="close-modal">Close</button><button class="primary" data-action="handoff-export">Save reviewed ZIP</button><button class="primary" data-action="handoff-local">Draft rationale with local Ollama</button>',true);}
function handoffSaveReview(){const input=$('#handoff-text');if(input)RH.text=input.value;for(const el of $$('[data-handoff-approved]'))RH.approved[el.dataset.handoffApproved]=el.checked;}
function handoffRedactionUI(){const f=RH.files.find(f=>f.id===RH.current);modal('Redact '+f.label,`<p>Check all pages. Draw rectangles over names, RUIDs, initials, labels, signatures or other identifiers. If none are present, choose No redaction needed below. Black areas permanently replace pixels in the exported copy.</p><div class="actions"><button data-action="handoff-prev"${RH.page===0?' disabled':''}>Previous page</button><span>Page ${RH.page+1} of ${f.pages}</span><button data-action="handoff-next"${RH.page===f.pages-1?' disabled':''}>Next page</button><button data-action="handoff-undo">Undo last box on this page</button></div><p class="help">Scanned text and handwriting are not automatically recognized. Include generous margins around identifiers.</p><canvas id="handoff-canvas" class="handoff-canvas" aria-label="Draw redaction rectangles over identifying information"></canvas><p id="handoff-image-status">Loading local page…</p>`,'<button data-action="handoff-back">Back to text</button><button data-action="handoff-no-redaction">No redaction needed — prepare clean copy</button><button class="primary" data-action="handoff-build">Prepare copy with my redactions</button>',true);const image=new Image();const expectedPage=RH.page;image.onload=()=>{if(!$('#handoff-canvas')||RH.current!==f.id||RH.page!==expectedPage)return;RH.image=image;const canvas=$('#handoff-canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;handoffDraw();$('#handoff-image-status').textContent='Drag on the page to add a black box.';let start=null;const point=e=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};canvas.onpointerdown=e=>{start=point(e);canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!start)return;const end=point(e);handoffDraw({page:RH.page,x0:Math.min(start.x,end.x),y0:Math.min(start.y,end.y),x1:Math.max(start.x,end.x),y1:Math.max(start.y,end.y)});};canvas.onpointerup=e=>{if(!start)return;const end=point(e);const box={page:RH.page,x0:Math.min(start.x,end.x),y0:Math.min(start.y,end.y),x1:Math.max(start.x,end.x),y1:Math.max(start.y,end.y)};start=null;if(box.x1-box.x0>.002&&box.y1-box.y0>.002){(RH.boxes[f.id]??=[]).push(box);delete RH.reviews[f.id];delete RH.approved[f.id];}handoffDraw();};canvas.onpointercancel=()=>{start=null;handoffDraw();};};image.onerror=()=>{$('#handoff-image-status').textContent='The local page could not be rendered. Close and retry.';};image.src=`${casePath()}/handoff/${RH.session_id}/image/${encodeURIComponent(f.id)}/${RH.page}`;}
function handoffDraw(extra){const c=$('#handoff-canvas');if(!c||!RH.image)return;const ctx=c.getContext('2d');ctx.drawImage(RH.image,0,0);ctx.fillStyle='black';for(const b of [...(RH.boxes[RH.current]||[]),...(extra?[extra]:[])])if(b.page===RH.page)ctx.fillRect(b.x0*c.width,b.y0*c.height,(b.x1-b.x0)*c.width,(b.y1-b.y0)*c.height);}
async function handoffAction(el){const a=el.dataset.action;if(a==='rationale-handoff'){handoffSelect();return;}if(a==='handoff-resume'){const data=await api(`${casePath()}/handoff`);if(!data.found)throw new Error('No unfinished handoff is saved for this case.');RH={...data,approved:{},case_id:S.detail.id};handoffReviewUI();return;}if(a==='handoff-prepare'){const payload={file_ids:$$('[data-handoff-file]:checked').map(x=>x.value),include_meetings:$('#handoff-meetings').checked,include_case_notes:$('#handoff-case-notes').checked};const data=await api(`${casePath()}/handoff`,payload);RH={...data,boxes:{},reviews:{},approved:{},case_id:S.detail.id};closeModal();handoffReviewUI();return;}if(!RH||RH.case_id!==S.detail.id)throw new Error('Prepare a new handoff for this case.');if(a==='handoff-redact'){handoffSaveReview();RH.current=el.dataset.id;RH.page=0;closeModal();handoffRedactionUI();return;}if(a==='handoff-prev'||a==='handoff-next'){RH.page+=a==='handoff-prev'?-1:1;closeModal();handoffRedactionUI();return;}if(a==='handoff-undo'){const boxes=RH.boxes[RH.current]||[];for(let i=boxes.length-1;i>=0;i--)if(boxes[i].page===RH.page){boxes.splice(i,1);delete RH.reviews[RH.current];delete RH.approved[RH.current];break;}handoffDraw();return;}if(a==='handoff-back'){closeModal();handoffReviewUI();return;}if(a==='handoff-build'||a==='handoff-no-redaction'){if(a==='handoff-no-redaction'&&(RH.boxes[RH.current]||[]).length)throw new Error('This document has redaction boxes. Prepare the copy with your redactions, or undo the boxes first.');const data=await api(`${casePath()}/handoff/${RH.session_id}/review`,{file_id:RH.current,boxes:RH.boxes[RH.current]||[]});RH.reviews[RH.current]=data;delete RH.approved[RH.current];closeModal();handoffReviewUI();return;}if(a==='handoff-export'||a==='handoff-local'){handoffSaveReview();if(!$('#handoff-text-approved').checked)throw new Error('Review and approve the anonymized text before exporting.');for(const f of RH.files.filter(f=>f.pages)){if(!RH.reviews[f.id])throw new Error(`${f.label}: review its pages and prepare a clean copy, even if no redaction is needed.`);if(!RH.approved[f.id])throw new Error(`${f.label}: open its prepared copy, then check the approval box beneath it.`);}const data=await api(`${casePath()}/handoff/${RH.session_id}/export`,{text:RH.text,approved:true,reviews:Object.fromEntries(Object.entries(RH.reviews).map(([id,r])=>[id,r.review_sha256]))});S.detail=(await api(casePath())).case;renderEvidence();closeModal();if(a==='handoff-local'){await LocalDrafting.open({endpoint:'/api/local-rationale',mode:'local',copyOnly:true,brief:'Rationale-'+RH.session_id+'.txt',target:{caseId:RH.case_id,sessionId:RH.session_id},token:S.boot.token,intro:'Only this approved handoff text and its reviewed redacted document copies go to local Ollama. Page observations may contain errors. Review the editable rationale; findings and sanctions remain your decisions.'});return;}modal('Rationale handoff saved',`<p>The reviewed text and redacted copies are saved locally. Nothing was sent. Keep the original evidence private.</p><a href="${attr(data.url)}" download="Rationale-handoff.zip">Download reviewed rationale ZIP</a>`,'<button data-action="close-modal">Done</button>');return;}}
